import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeExtern, Offre, 
  CalculatedGros, CalculatedExtern, DashboardData,
  GrosStatus, ExternStatus, OffreType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

// Supabase Initialization
const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: Omit<CommandeGros, 'id'>[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: Omit<CommandeExtern, 'id'>[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: Omit<Offre, 'id'>[]) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);

const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);

  const [gros, setGros] = useState<CommandeGros[]>(() => {
    const saved = localStorage.getItem('merch_dz_gros');
    return saved ? JSON.parse(saved) : INITIAL_GROS;
  });

  const [extern, setExtern] = useState<CommandeExtern[]>(() => {
    const saved = localStorage.getItem('merch_dz_extern');
    return saved ? JSON.parse(saved) : INITIAL_EXTERN;
  });

  const [offres, setOffres] = useState<Offre[]>(() => {
    const saved = localStorage.getItem('merch_dz_offres');
    return saved ? JSON.parse(saved) : INITIAL_OFFRES;
  });

  // Local Persist
  useEffect(() => { localStorage.setItem('merch_dz_gros', JSON.stringify(gros)); }, [gros]);
  useEffect(() => { localStorage.setItem('merch_dz_extern', JSON.stringify(extern)); }, [extern]);
  useEffect(() => { localStorage.setItem('merch_dz_offres', JSON.stringify(offres)); }, [offres]);

  // Cloud Sync Logic
  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      // In a real implementation, we would fetch and merge here.
      // For this OS version, we treat Local as Source of Truth and Upsert to Cloud.
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres })
      ]);
    } catch (e) {
      console.error("Cloud Sync Failed:", e);
    } finally {
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, [gros, extern, offres, isAuthenticated]);

  // Initial Cloud Fetch on Login
  useEffect(() => {
    const initFetch = async () => {
      if (!supabase || !isAuthenticated) return;
      setIsSyncing(true);
      try {
        const [gRes, eRes, oRes] = await Promise.all([
          supabase.from('gros_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('detail_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('offres_frais').select('data').eq('id', 'current_state').single()
        ]);
        if (gRes.data?.data) setGros(gRes.data.data);
        if (eRes.data?.data) setExtern(eRes.data.data);
        if (oRes.data?.data) setOffres(oRes.data.data);
      } catch (e) {
        console.warn("No cloud data found yet, using local storage.");
      } finally {
        setIsSyncing(false);
      }
    };
    initFetch();
  }, [isAuthenticated]);

  // Auto-sync on changes (Debounced ideally, but here direct for simplicity)
  useEffect(() => {
    const timer = setTimeout(() => {
      if (isAuthenticated) syncData();
    }, 2000);
    return () => clearTimeout(timer);
  }, [gros, extern, offres, syncData, isAuthenticated]);

  const login = (password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  };

  const updateGros = (id: string, field: keyof CommandeGros, value: any) => {
    setGros(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addGros = () => {
    const newId = Date.now().toString() + Math.random().toString(36).substr(2, 9);
    setGros(prev => [
      ...prev,
      {
        id: newId,
        reference: `G${prev.length + 1}`,
        client_name: '', client_phone: '',
        date_created: new Date().toISOString().split('T')[0],
        prix_achat_article: 0, impression: false, prix_impression: 0,
        prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: ''
      }
    ]);
  };

  const deleteGros = (id: string) => {
    setGros(prev => prev.filter(item => String(item.id) !== String(id)));
  };

  const importGros = (newData: Omit<CommandeGros, 'id'>[]) => {
    const itemsWithIds = newData.map(item => ({ ...item, id: Date.now().toString() + Math.random().toString(36).substr(2, 9) }));
    setGros(prev => [...prev, ...itemsWithIds]);
  };

  const updateExtern = (id: string, field: keyof CommandeExtern, value: any) => {
    setExtern(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addExtern = () => {
    const newId = Date.now().toString() + Math.random().toString(36).substr(2, 9);
    setExtern(prev => [
      ...prev,
      {
        id: newId, reference: `D${prev.length + 1}`,
        client_name: '', client_phone: '',
        date_created: new Date().toISOString().split('T')[0],
        prix_achat_article: 0, impression: false, prix_impression: 0,
        prix_vente: 0, status: ExternStatus.EN_PRODUCTION, stock_note: ''
      }
    ]);
  };

  const deleteExtern = (id: string) => {
    setExtern(prev => prev.filter(item => String(item.id) !== String(id)));
  };

  const importExtern = (newData: Omit<CommandeExtern, 'id'>[]) => {
    const itemsWithIds = newData.map(item => ({ ...item, id: Date.now().toString() + Math.random().toString(36).substr(2, 9) }));
    setExtern(prev => [...prev, ...itemsWithIds]);
  };

  const updateOffre = (id: string, field: keyof Offre, value: any) => {
    setOffres(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addOffre = () => {
    const newId = Date.now().toString() + Math.random().toString(36).substr(2, 9);
    setOffres(prev => [
      ...prev,
      {
        id: newId, date: new Date().toISOString().split('T')[0],
        type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: ''
      }
    ]);
  };

  const deleteOffre = (id: string) => {
    setOffres(prev => prev.filter(item => String(item.id) !== String(id)));
  };

  const importOffres = (newData: Omit<Offre, 'id'>[]) => {
    const itemsWithIds = newData.map(item => ({ ...item, id: Date.now().toString() + Math.random().toString(36).substr(2, 9) }));
    setOffres(prev => [...prev, ...itemsWithIds]);
  };

  const getCalculatedGros = useCallback((): CalculatedGros[] => {
    return gros.map(item => {
      const cost = Number(item.prix_achat_article) + Number(item.prix_impression);
      const profit = Number(item.prix_vente) - cost;
      return {
        ...item, cost,
        profit_encaisse: item.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0,
        profit_attendu: item.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0,
        perte: item.status === GrosStatus.RETOUR ? cost : 0
      };
    });
  }, [gros]);

  const getCalculatedExtern = useCallback((): CalculatedExtern[] => {
    return extern.map(item => {
      const cost = Number(item.prix_achat_article) + Number(item.prix_impression);
      const profit = Number(item.prix_vente) - cost;
      return {
        ...item, cost,
        profit_reel: item.status === ExternStatus.LIVREE ? profit : 0,
        perte: item.status === ExternStatus.RETOUR ? cost : 0
      };
    });
  }, [extern]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();
    const cExtern = getCalculatedExtern();
    const grosEncaisse = cGros.reduce((acc, curr) => acc + curr.profit_encaisse, 0);
    const externEncaisse = cExtern.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const profitAttendu = cGros.reduce((acc, curr) => acc + curr.profit_attendu, 0);
    const pertes = cGros.reduce((acc, curr) => acc + curr.perte, 0) + cExtern.reduce((acc, curr) => acc + curr.perte, 0);
    const rev = offres.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = offres.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const netOffres = rev - exp;
    const encaisseReel = grosEncaisse + externEncaisse;
    const profitNetFinal = encaisseReel + profitAttendu + netOffres - pertes;
    return {
      encaisse_reel: encaisseReel,
      profit_attendu: profitAttendu,
      pertes: pertes,
      net_offres: netOffres,
      profit_net_final: profitNetFinal
    };
  }, [getCalculatedGros, getCalculatedExtern, offres]);

  return (
    <AppContext.Provider value={{ 
      gros, extern, offres, isAuthenticated, login, logout, isSyncing, isCloudActive,
      updateGros, addGros, deleteGros, importGros,
      updateExtern, addExtern, deleteExtern, importExtern,
      updateOffre, addOffre, deleteOffre, importOffres,
      getCalculatedGros, getCalculatedExtern, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useAppStore must be used within AppProvider");
  return context;
};

import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAppStore } from '../store.tsx';
import { 
  LayoutDashboard, 
  Truck, 
  ShoppingBag, 
  TrendingUp,
  User,
  LogOut,
  ShieldCheck,
  Cloud,
  CloudOff,
  RefreshCw
} from 'lucide-react';

const Sidebar: React.FC = () => {
  const { logout, isSyncing, isCloudActive, syncData } = useAppStore();
  const navItems = [
    { to: '/', label: 'Tableau de bord', icon: LayoutDashboard },
    { to: '/gros', label: 'Commandes GROS', icon: Truck },
    { to: '/detail', label: 'Commandes Détail', icon: ShoppingBag },
    { to: '/offres', label: 'Offres & Frais', icon: TrendingUp },
  ];

  return (
    <aside className="w-64 bg-slate-900 text-slate-400 h-screen sticky top-0 flex flex-col z-50">
      <div className="p-8 flex items-center gap-3">
        <div className="bg-blue-500 w-10 h-10 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg shadow-blue-500/20">M</div>
        <div>
          <h1 className="font-black text-white text-lg leading-tight tracking-tighter">Merch By DZ</h1>
          <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Back-Office v3.0</p>
        </div>
      </div>

      <nav className="flex-1 px-4 py-4 space-y-1.5">
        <p className="px-4 text-[10px] font-black text-slate-600 uppercase tracking-widest mb-4">Menu Principal</p>
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            className={({ isActive }) => `
              flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all duration-300 group
              ${isActive 
                ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-100'}
            `}
          >
            {({ isActive }) => (
              <>
                <item.icon size={20} className={isActive ? 'text-white' : 'group-hover:scale-110 transition-transform'} />
                <span className="font-bold text-sm tracking-tight">{item.label}</span>
              </>
            )}
          </NavLink>
        ))}
      </nav>

      {/* Cloud Sync Status */}
      <div className="px-6 py-4 border-t border-slate-800/50">
        <div className="flex items-center justify-between mb-2">
           <div className="flex items-center gap-2">
            {isCloudActive ? (
              <Cloud size={14} className={isSyncing ? "text-blue-400 animate-pulse" : "text-emerald-500"} />
            ) : (
              <CloudOff size={14} className="text-slate-600" />
            )}
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">
              {isSyncing ? "Synchronisation..." : (isCloudActive ? "Cloud Actif" : "Mode Local")}
            </span>
           </div>
           {isCloudActive && (
             <button 
              onClick={() => syncData()}
              className="p-1 hover:bg-slate-800 rounded-md transition-colors"
              title="Forcer la synchronisation"
             >
               <RefreshCw size={12} className={`${isSyncing ? 'animate-spin' : ''}`} />
             </button>
           )}
        </div>
        <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
          <div className={`h-full bg-blue-500 transition-all duration-1000 ${isSyncing ? 'w-full opacity-100' : 'w-0 opacity-0'}`}></div>
        </div>
      </div>

      <div className="p-4 mx-4 mb-8 bg-slate-800/50 rounded-3xl border border-slate-800">
        <div className="flex items-center gap-3 px-2 py-2 mb-4">
          <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-slate-400">
            <User size={16} />
          </div>
          <div className="flex-1 truncate">
            <p className="text-xs font-bold text-white truncate">Administrateur</p>
            <p className="text-[10px] text-slate-500 flex items-center gap-1">
              <ShieldCheck size={10} className="text-emerald-500" /> Session Sécurisée
            </p>
          </div>
        </div>
        <button 
          onClick={() => { if(confirm('Confirmer la déconnexion ?')) logout(); }}
          className="w-full flex items-center justify-center gap-2 px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-red-400/10 rounded-2xl transition-all font-bold text-xs"
        >
          <LogOut size={16} />
          <span>Quitter le système</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

