import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeExtern, Offre, 
  CalculatedGros, CalculatedExtern, DashboardData,
  GrosStatus, ExternStatus, OffreType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

// Dynamic credential detection (Works with Netlify Build Environment)
// Netlify integration typically provides SUPABASE_URL and SUPABASE_ANON_KEY
const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';

// Initialize Supabase Client
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: Omit<CommandeGros, 'id'>[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: Omit<CommandeExtern, 'id'>[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: Omit<Offre, 'id'>[]) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);

const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);

  // Use localStorage as the "Local Source" for speed
  const [gros, setGros] = useState<CommandeGros[]>(() => {
    const saved = localStorage.getItem('merch_dz_gros');
    return saved ? JSON.parse(saved) : INITIAL_GROS;
  });

  const [extern, setExtern] = useState<CommandeExtern[]>(() => {
    const saved = localStorage.getItem('merch_dz_extern');
    return saved ? JSON.parse(saved) : INITIAL_EXTERN;
  });

  const [offres, setOffres] = useState<Offre[]>(() => {
    const saved = localStorage.getItem('merch_dz_offres');
    return saved ? JSON.parse(saved) : INITIAL_OFFRES;
  });

  // Local Persistence
  useEffect(() => { localStorage.setItem('merch_dz_gros', JSON.stringify(gros)); }, [gros]);
  useEffect(() => { localStorage.setItem('merch_dz_extern', JSON.stringify(extern)); }, [extern]);
  useEffect(() => { localStorage.setItem('merch_dz_offres', JSON.stringify(offres)); }, [offres]);

  // Cloud Sync Logic: Pushes local data to the cloud
  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres })
      ]);
      console.log("Cloud Sync Successful");
    } catch (e) {
      console.error("Cloud Sync Failed. Ensure you created tables in Supabase.", e);
    } finally {
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, [gros, extern, offres, isAuthenticated]);

  // Cloud Fetch: On startup/login, pull latest from cloud
  useEffect(() => {
    const initFetch = async () => {
      if (!supabase || !isAuthenticated) return;
      setIsSyncing(true);
      try {
        const [gRes, eRes, oRes] = await Promise.all([
          supabase.from('gros_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('detail_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('offres_frais').select('data').eq('id', 'current_state').single()
        ]);

        if (gRes.data?.data) setGros(gRes.data.data);
        if (eRes.data?.data) setExtern(eRes.data.data);
        if (oRes.data?.data) setOffres(oRes.data.data);
      } catch (e) {
        console.warn("Cloud data fetch failed (likely no records yet). Using local data.");
      } finally {
        setIsSyncing(false);
      }
    };
    initFetch();
  }, [isAuthenticated]);

  // Background Sync Trigger
  useEffect(() => {
    const timer = setTimeout(() => {
      if (isAuthenticated) syncData();
    }, 5000); // Sync every 5 seconds if changes occur
    return () => clearTimeout(timer);
  }, [gros, extern, offres, syncData, isAuthenticated]);

  const login = (password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  };

  const updateGros = (id: string, field: keyof CommandeGros, value: any) => {
    setGros(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addGros = () => {
    const newId = Date.now().toString() + Math.random().toString(36).substr(2, 9);
    setGros(prev => [
      ...prev,
      {
        id: newId,
