  const deleteGros = (id: string) => setGros(prev => prev.filter(i => i.id !== id));
  // Implementation for importGros
  const importGros = (data: any[]) => setGros(data.map(i => ({ ...i, id: i.id || (Date.now() + Math.random()).toString() })));

