```sql
-- Create tables for Merch By DZ
create table if not exists gros_orders (
  id text primary key,
  data jsonb not null,
  updated_at timestamp with time zone default now()
);

create table if not exists detail_orders (
  id text primary key,
  data jsonb not null,
  updated_at timestamp with time zone default now()
);

create table if not exists offres_frais (
  id text primary key,
  data jsonb not null,
  updated_at timestamp with time zone default now()
);

create table if not exists inventory (
  id text primary key,
  data jsonb not null,
  updated_at timestamp with time zone default now()
);

-- Enable Row Level Security (RLS) but allow all for now for internal tool simplicity
-- Note: In a production public app, you would restrict this to auth users only.
alter table gros_orders enable row level security;
alter table detail_orders enable row level security;
alter table offres_frais enable row level security;
alter table inventory enable row level security;

create policy "Allow all" on gros_orders for all using (true) with check (true);
create policy "Allow all" on detail_orders for all using (true) with check (true);
create policy "Allow all" on offres_frais for all using (true) with check (true);
