            <div>
              <span className="block text-[10px] font-black uppercase tracking-widest text-slate-500">
                {isSyncing ? "Sync..." : (isCloudActive ? "Cloud à jour" : "Mode Local")}
              </span>
              {lastSynced && isCloudActive && !isSyncing && (
                <span className="block text-[9px] text-slate-600 font-medium">Vu à {lastSynced}</span>
              )}
            </div>
           </div>
           {isCloudActive && (
             <button 
              onClick={() => syncData()}
              className={`p-2 hover:bg-slate-800 rounded-xl transition-all ${isSyncing ? 'opacity-50 pointer-events-none' : ''}`}
             >
               <Cloud size={14} className={isSyncing ? 'text-blue-400' : 'text-slate-400'} />
             </button>
           )}
        </div>
      </div>

      <div className="p-4 mx-4 mb-8 bg-slate-800/50 rounded-3xl border border-slate-800">
        <button 
          onClick={() => { if(confirm('Confirmer la déconnexion ?')) logout(); }}
          className="w-full flex items-center justify-center gap-2 px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-red-400/10 rounded-2xl transition-all font-bold text-xs"
        >
          <LogOut size={16} />
          <span>Quitter</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useMemo, useState } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area
} from 'recharts';
import { 
  Clock, 
  AlertCircle, 
  ArrowRightLeft, 
  TrendingUp,
  Banknote,
  Calendar,
  RotateCcw,
  Truck,
  Wallet
} from 'lucide-react';
import { GrosStatus, ExternStatus, OffreType } from '../types.ts';

const Dashboard: React.FC = () => {
  const { gros, extern, offres, charges, getCalculatedGros, getCalculatedExtern } = useAppStore();

  // Date Filtration States
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const cGros = getCalculatedGros();
  const cExtern = getCalculatedExtern();

  // Filtered Datasets
  const filteredData = useMemo(() => {
    const filterByDate = (dateStr: string) => {
      if (!dateStart && !dateEnd) return true;
      if (dateStart && dateStr < dateStart) return false;
      if (dateEnd && dateStr > dateEnd) return false;
      return true;
    };

    const fGros = cGros.filter(item => filterByDate(item.date_created));
    const fExtern = cExtern.filter(item => filterByDate(item.date_created));
    const fOffres = offres.filter(item => filterByDate(item.date));
    const fCharges = charges.filter(item => filterByDate(item.date));

    return { fGros, fExtern, fOffres, fCharges };
  }, [cGros, cExtern, offres, charges, dateStart, dateEnd]);

  // Recalculate KPIs based on filtered data
  const metrics = useMemo(() => {
    const { fGros, fExtern, fOffres, fCharges } = filteredData;

    const encaisse_reel = fGros.reduce((acc, curr) => acc + curr.profit_encaisse, 0) + 
                         fExtern.reduce((acc, curr) => acc + curr.profit_reel, 0);

    const profit_attendu = fGros.reduce((acc, curr) => acc + curr.profit_attendu, 0);

    const pertes = fGros.reduce((acc, curr) => acc + curr.perte, 0) + 
                   fExtern.reduce((acc, curr) => acc + curr.perte, 0);

    const rev = fOffres.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = fOffres.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const net_offres = rev - exp;

    const total_charges = fCharges.reduce((acc, curr) => acc + Number(curr.montant), 0);

    const profit_net_final = encaisse_reel + profit_attendu + net_offres - pertes - total_charges;

    return {
      encaisse_reel,
      profit_attendu,
      pertes,
      net_offres,
      total_charges,
      profit_net_final,
      total_orders: fGros.length + fExtern.length,
      total_expenses: exp + total_charges
    };
  }, [filteredData]);

  const kpis = [
    { label: 'Encaisse Réel', value: metrics.encaisse_reel, icon: Banknote, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'Profit Attendu', value: metrics.profit_attendu, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Pertes (Retours)', value: metrics.pertes, icon: AlertCircle, color: 'text-red-600', bg: 'bg-red-50' },
    { label: 'Les Charges', value: metrics.total_charges, icon: Wallet, color: 'text-orange-600', bg: 'bg-orange-50' },
  ];

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('fr-DZ', { style: 'currency', currency: 'DZD', maximumFractionDigits: 0 }).format(val);
  };

  const timeSeriesData = useMemo(() => {
    const { fGros, fExtern, fOffres, fCharges } = filteredData;
    const dailyMap: Record<string, { date: string; profit: number }> = {};

    const ensureDate = (date: string) => {
      if (!dailyMap[date]) dailyMap[date] = { date, profit: 0 };
    };

    fGros.forEach(item => {
      ensureDate(item.date_created);
      if (item.status === GrosStatus.LIVREE_ENCAISSE) {
        dailyMap[item.date_created].profit += (item.prix_vente - item.cost);
      } else if (item.status === GrosStatus.RETOUR) {
        dailyMap[item.date_created].profit -= item.cost;
      }
    });

    fExtern.forEach(item => {
      ensureDate(item.date_created);
      if (item.status === ExternStatus.LIVREE) {
        dailyMap[item.date_created].profit += (item.prix_vente - item.cost);
      } else if (item.status === ExternStatus.RETOUR) {
        dailyMap[item.date_created].profit -= item.cost;
      }
    });

    fOffres.forEach(item => {
      ensureDate(item.date);
      if (item.type === OffreType.REVENUE) {
        dailyMap[item.date].profit += Number(item.montant);
      } else {
        dailyMap[item.date].profit -= Number(item.montant);
      }
    });

    fCharges.forEach(item => {
      ensureDate(item.date);
      dailyMap[item.date].profit -= Number(item.montant);
    });

    return Object.values(dailyMap)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredData]);

  const resetFilters = () => {
    setDateStart('');
    setDateEnd('');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header & Filter Section */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Analyse financière dynamique par période.</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 bg-white p-2 rounded-2xl border border-slate-200 shadow-sm self-start">
          <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
            <Calendar size={16} className="text-blue-500" />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Du</span>
            <input 
              type="date" 
              value={dateStart}
              onChange={(e) => setDateStart(e.target.value)}
              className="bg-transparent text-xs font-bold outline-none text-slate-700"
            />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Au</span>
            <input 
              type="date" 
              value={dateEnd}
              onChange={(e) => setDateEnd(e.target.value)}
              className="bg-transparent text-xs font-bold outline-none text-slate-700"
            />
          </div>
          {(dateStart || dateEnd) && (
            <button 
              onClick={resetFilters}
              className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
              title="Réinitialiser"
            >
              <RotateCcw size={18} />
            </button>
          )}
          <div className="hidden md:flex flex-col items-end px-4 border-l border-slate-100">
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aujourd'hui</span>
             <span className="text-xs font-bold text-slate-700">{new Date().toLocaleDateString('fr-FR')}</span>
          </div>
        </div>
      </div>

      {/* KPI Cards Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md hover:-translate-y-1">
            <div className={`w-12 h-12 rounded-2xl ${kpi.bg} flex items-center justify-center mb-6`}>
              <kpi.icon className={kpi.color} size={24} />
            </div>
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{kpi.label}</p>
            <h3 className="text-2xl font-black text-slate-900">{formatCurrency(kpi.value)}</h3>
          </div>
        ))}
      </div>

      {/* Main Analysis Section */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Profit Flow Chart */}
        <div className="xl:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h4 className="font-bold text-slate-800 text-lg">Flux de Profit Périodique</h4>
            <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <span className="w-2 h-2 rounded-full bg-emerald-500"></span> Profit Net Quotidiens
            </div>
          </div>
          <div className="h-[350px]">
            {timeSeriesData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={timeSeriesData}>
                  <defs>
                    <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                      <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis 
                    dataKey="date" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} 
                    dy={10}
                    tickFormatter={(val) => new Date(val).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })}
                  />
                  <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 600}} />
                  <Tooltip 
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                    formatter={(val: number) => [formatCurrency(val), 'Profit']}
                  />
                  <Area type="monotone" dataKey="profit" stroke="#10b981" fillOpacity={1} fill="url(#colorProfit)" strokeWidth={3} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-2">
                <Calendar size={48} className="opacity-10" />
                <p className="text-sm font-medium">Aucune donnée pour cette période</p>
              </div>
            )}
          </div>
        </div>

        {/* Summary Card */}
        <div className="bg-slate-900 text-white p-8 rounded-3xl shadow-xl shadow-slate-200 relative overflow-hidden flex flex-col">
          <div className="relative z-10 flex flex-col h-full">
            <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-4">Total Net (Sur Période)</p>
            <h4 className="text-4xl font-black mb-2 tracking-tighter transition-all">
              {formatCurrency(metrics.profit_net_final)}
            </h4>
            <p className="text-slate-400 text-sm font-medium">
              Bénéfice calculé après toutes les opérations incluant les charges de la période.
            </p>

            <div className="mt-auto space-y-4 pt-8">
              <div className="flex items-center justify-between p-4 bg-slate-800/50 rounded-2xl border border-slate-700">
                <div>
                  <p className="text-[10px] font-black text-slate-500 uppercase">Volume Commandes</p>
                  <span className="text-sm font-black text-white">{metrics.total_orders}</span>
                </div>
                <Truck size={20} className="text-blue-500/50" />
              </div>
              <div className="flex items-center justify-between p-4 bg-slate-800/50 rounded-2xl border border-slate-700">
                <div>
                  <p className="text-[10px] font-black text-slate-500 uppercase">Total Frais & Charges</p>
                  <span className="text-sm font-black text-orange-400">-{formatCurrency(metrics.total_expenses)}</span>
                </div>
                <AlertCircle size={20} className="text-orange-500/50" />
              </div>
            </div>
          </div>
          <TrendingUp size={120} className="absolute -bottom-8 -right-8 text-white/5 rotate-12" />
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { Plus, Trash2, Search, Wallet, Calendar, UserCheck, Briefcase } from 'lucide-react';

const PRESET_LABELS = [
  'Salaire Billel',
  'Salaire Oussama',
  'Salaire Ahmed',
  'Salaire Assistante',
  'Transport',
  'Service online',
  'Autre',
  'salaire teleoperatrice',
  'locale',
  'investiseur salaise'
];

const Charges: React.FC = () => {
  const { charges, updateCharge, addCharge, deleteCharge } = useAppStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const filteredData = useMemo(() => {
    return charges.filter(item => {
      const matchesSearch = item.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          item.note.toLowerCase().includes(searchTerm.toLowerCase());

      const itemDate = item.date;
      const matchesStart = !dateStart || itemDate >= dateStart;
      const matchesEnd = !dateEnd || itemDate <= dateEnd;

      return matchesSearch && matchesStart && matchesEnd;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [charges, searchTerm, dateStart, dateEnd]);

  const stats = useMemo(() => {
    const total = filteredData.reduce((acc, curr) => acc + Number(curr.montant), 0);
    const count = filteredData.length;
    const avg = count > 0 ? total / count : 0;
    return { total, count, avg };
  }, [filteredData]);

  const formatPrice = (val: number) => {
    return val.toLocaleString('fr-DZ') + ' DA';
  };

  const resetFilters = () => {
    setSearchTerm('');
    setDateStart('');
    setDateEnd('');
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Les Charges</h2>
          <p className="text-slate-500 text-sm">Gestion des salaires, loyers et charges fixes.</p>
        </div>
        <div className="flex flex-wrap gap-2">
           <div className="relative group">
            <button 
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
            >
              <Plus size={16} /> Ajouter une Charge
            </button>
            <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 p-2">
               <p className="px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 mb-1">Presets</p>
               {PRESET_LABELS.map(label => (
                 <button 
                  key={label}
                  onClick={() => addCharge(label)}
                  className="w-full text-left px-3 py-2 hover:bg-blue-50 rounded-xl text-xs font-bold text-slate-600 hover:text-blue-600 transition-colors"
                 >
                   {label}
                 </button>
               ))}
               <button 
                  onClick={() => addCharge('Nouvelle Charge')}
                  className="w-full text-left px-3 py-2 mt-1 bg-slate-50 hover:bg-slate-100 rounded-xl text-xs font-black text-slate-400 text-center uppercase tracking-widest"
               >
                 + Libre
               </button>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard label="Total Charges (Période)" value={formatPrice(stats.total)} icon={Wallet} color="text-orange-600" bg="bg-orange-50" />
        <StatCard label="Nombre d'Entrées" value={stats.count} icon={Briefcase} color="text-blue-600" bg="bg-blue-50" />
        <StatCard label="Moyenne / Entrée" value={formatPrice(stats.avg)} icon={UserCheck} color="text-slate-600" bg="bg-slate-50" />
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Rechercher par label ou note..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all text-sm font-medium"
            />
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-3 py-1.5 shadow-sm">
              <Calendar size={14} className="text-slate-400" />
              <input 
                type="date" 
                value={dateStart} 
                onChange={(e) => setDateStart(e.target.value)}
                className="text-xs outline-none bg-transparent font-medium text-slate-700"
              />
              <span className="text-slate-300">à</span>
              <input 
                type="date" 
                value={dateEnd} 
                onChange={(e) => setDateEnd(e.target.value)}
                className="text-xs outline-none bg-transparent font-medium text-slate-700"
              />
            </div>
            {(searchTerm || dateStart || dateEnd) && (
              <button 
                onClick={resetFilters}
                className="text-xs font-bold text-blue-600 hover:text-blue-700 transition-colors"
              >
                Réinitialiser
              </button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/80 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Libellé</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Note / Détails</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Montant (DA)</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredData.map((item) => (
                <tr key={item.id} className="hover:bg-orange-50/30 transition-colors group">
                  <td className="p-2">
                    <EditableCell type="date" value={item.date} onSave={(v) => updateCharge(item.id, 'date', v)} className="text-slate-600 font-medium" />
                  </td>
                  <td className="p-2">
                    <EditableCell value={item.label} onSave={(v) => updateCharge(item.id, 'label', v)} className="font-black text-slate-800" />
                  </td>
                  <td className="p-2 text-slate-500">
                    <EditableCell value={item.note} onSave={(v) => updateCharge(item.id, 'note', v)} className="text-slate-500 italic text-xs" />
                  </td>
                  <td className="p-2 text-right">
                    <EditableCell type="number" value={item.montant} onSave={(v) => updateCharge(item.id, 'montant', v)} className="text-right text-orange-600 font-black" />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      onClick={() => {
                        if(confirm('Supprimer cette charge ?')) deleteCharge(item.id);
                      }}
                      className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50"
                    >
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-12 text-center text-slate-400 font-medium">
                    Aucune charge enregistrée pour cette période.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Charges;

import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar.tsx';
import Dashboard from './pages/Dashboard.tsx';
import CommandesGros from './pages/CommandesGros.tsx';
import CommandesDetail from './pages/CommandesDetail.tsx';
import Inventory from './pages/Inventory.tsx';
import Offres from './pages/Offres.tsx';
import Charges from './pages/Charges.tsx';
import LoginPage from './pages/LoginPage.tsx';
import { AppProvider, useAppStore } from './store.tsx';

const ProtectedLayout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated } = useAppStore();

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="flex min-h-screen">
      <Sidebar />
      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          {children}
        </div>
      </main>
    </div>
  );
};

const AppRoutes: React.FC = () => {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route path="/" element={<ProtectedLayout><Dashboard /></ProtectedLayout>} />
      <Route path="/gros" element={<ProtectedLayout><CommandesGros /></ProtectedLayout>} />
      <Route path="/detail" element={<ProtectedLayout><CommandesDetail /></ProtectedLayout>} />
      <Route path="/inventory" element={<ProtectedLayout><Inventory /></ProtectedLayout>} />
      <Route path="/charges" element={<ProtectedLayout><Charges /></ProtectedLayout>} />
      <Route path="/offres" element={<ProtectedLayout><Offres /></ProtectedLayout>} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <Router>
        <AppRoutes />
      </Router>
    </AppProvider>
  );
};

export default App;

export enum GrosStatus {
  EN_PRODUCTION = 'en_production',
  EN_LIVRAISON = 'en_livraison',
  LIVREE_NON_ENCAISSE = 'livree_non_encaisse',
  LIVREE_ENCAISSE = 'livree_encaisse',
  RETOUR = 'retour'
}

export enum ExternStatus {
  EN_PRODUCTION = 'en_production',
  LIVREE = 'livree',
  RETOUR = 'retour'
}

export enum OffreType {
  REVENUE = 'revenue',
  EXPENSE = 'expense'
}

export enum OffreCategory {
  ADS = 'ads',
  CREATIVE = 'creative',
  PACKAGING = 'packaging',
  TRANSPORT = 'transport',
  MANUAL = 'manual',
  OTHER = 'other'
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  min_stock: number;
  unit_cost: number;
  supplier: string;
}

export interface Charge {
  id: string;
  date: string;
  label: string;
  montant: number;
  note: string;
}

export interface CommandeGros {
  id: string;
  reference: string;
  client_name: string;
  client_phone: string;
  date_created: string;
  prix_achat_article: number;
  impression: boolean;
  prix_impression: number;
  prix_vente: number;
  status: GrosStatus;
  stock_note: string;
}

export interface CommandeExtern {
  id: string;
  reference: string;
  client_name: string;
  client_phone: string;
  date_created: string;
  prix_achat_article: number;
  impression: boolean;
  prix_impression: number;
  prix_vente: number;
  status: ExternStatus;
  stock_note: string;
  vendeur_name: string;
  vendeur_benefice: number;
}

export interface CalculatedGros extends CommandeGros {
  cost: number;
  profit_encaisse: number;
  profit_attendu: number;
  perte: number;
}

export interface CalculatedExtern extends CommandeExtern {
  cost: number;
  profit_reel: number;
  perte: number;
}

export interface DashboardData {
  encaisse_reel: number;
  profit_attendu: number;
  pertes: number;
  net_offres: number;
  total_charges: number;
  profit_net_final: number;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeExtern, Offre, InventoryItem, Charge,
  CalculatedGros, CalculatedExtern, DashboardData,
  GrosStatus, ExternStatus, OffreType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: any[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);
const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [extern, setExtern] = useState<CommandeExtern[]>(() => {
    const raw = JSON.parse(localStorage.getItem('merch_dz_extern') || JSON.stringify(INITIAL_EXTERN));
    return raw.map((i: any) => ({
      ...i,
      vendeur_name: i.vendeur_name || '',
      vendeur_benefice: i.vendeur_benefice || 0
    }));
  });
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_extern', JSON.stringify(extern));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
  }, [gros, extern, offres, inventory, charges]);

  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, extern, offres, inventory, charges, isAuthenticated]);

  useEffect(() => {
    const initFetch = async () => {
      if (!supabase || !isAuthenticated) return;
      setIsSyncing(true);
      try {
        const [gRes, eRes, oRes, iRes, cRes] = await Promise.all([
          supabase.from('gros_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('detail_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('offres_frais').select('data').eq('id', 'current_state').single(),
          supabase.from('inventory').select('data').eq('id', 'current_state').single(),
          supabase.from('les_charges').select('data').eq('id', 'current_state').single()
        ]);
        if (gRes.data?.data) setGros(gRes.data.data);
        if (eRes.data?.data) {
          const mapped = eRes.data.data.map((i: any) => ({
            ...i,
            vendeur_name: i.vendeur_name || '',
            vendeur_benefice: i.vendeur_benefice || 0
          }));
          setExtern(mapped);
        }
        if (oRes.data?.data) setOffres(oRes.data.data);
        if (iRes.data?.data) setInventory(iRes.data.data);
        if (cRes.data?.data) setCharges(cRes.data.data);
      } catch (e) { console.warn("Cloud pull failed or empty."); }
      finally { setIsSyncing(false); }
    };
    initFetch();
  }, [isAuthenticated]);

  useEffect(() => {
    const timer = setTimeout(() => { if (isAuthenticated) syncData(); }, 10000);
    return () => clearTimeout(timer);
  }, [gros, extern, offres, inventory, charges, syncData, isAuthenticated]);

  const login = (password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  };

  // Updaters
  const updateGros = (id: string, field: keyof CommandeGros, value: any) => setGros(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addGros = () => setGros(p => [...p, { id: Date.now().toString(), reference: `G${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' }]);
  const deleteGros = (id: string) => setGros(prev => prev.filter(i => i.id !== id));
  const importGros = (data: any[]) => setGros(data.map(i => ({ ...i, id: i.id || (Date.now() + Math.random()).toString() })));

  const updateExtern = (id: string, field: keyof CommandeExtern, value: any) => setExtern(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addExtern = () => setExtern(p => [...p, { id: Date.now().toString(), reference: `SIT-${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: ExternStatus.EN_PRODUCTION, stock_note: '', vendeur_name: '', vendeur_benefice: 0 }]);
  const deleteExtern = (id: string) => setExtern(prev => prev.filter(i => i.id !== id));
  const importExtern = (data: any[]) => setExtern(data.map(i => ({ ...i, id: i.id || (Date.now() + Math.random()).toString(), vendeur_name: i.vendeur_name || '', vendeur_benefice: i.vendeur_benefice || 0 })));

  const updateOffre = (id: string, field: keyof Offre, value: any) => setOffres(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addOffre = () => setOffres(p => [...p, { id: Date.now().toString(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }]);
  const deleteOffre = (id: string) => setOffres(prev => prev.filter(i => i.id !== id));
  const importOffres = (data: any[]) => setOffres(data.map(i => ({ ...i, id: i.id || (Date.now() + Math.random()).toString() })));

  const updateInventory = (id: string, field: keyof InventoryItem, value: any) => setInventory(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addInventory = () => setInventory(p => [...p, { id: Date.now().toString(), name: 'Nouveau Stock', sku: 'SKU-'+p.length, quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }]);
  const deleteInventory = (id: string) => setInventory(prev => prev.filter(i => i.id !== id));

  const updateCharge = (id: string, field: keyof Charge, value: any) => setCharges(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addCharge = (label: string = 'Autre') => setCharges(p => [...p, { id: Date.now().toString(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }]);
  const deleteCharge = (id: string) => setCharges(prev => prev.filter(i => i.id !== id));

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { ...i, cost, profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, perte: i.status === GrosStatus.RETOUR ? cost : 0 };
  }), [gros]);

  const getCalculatedExtern = useCallback((): CalculatedExtern[] => extern.map(i => {
    // Coût Total = Achat + Impression
    const raw_cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    // Profit = Vente - (Coût Total + Bénéfice Vendeur)
    const profit = Number(i.prix_vente) - (raw_cost + Number(i.vendeur_benefice));

    return { 
      ...i, 
      cost: raw_cost, 
      profit_reel: i.status === ExternStatus.LIVREE ? profit : 0, 
      perte: i.status === ExternStatus.RETOUR ? raw_cost : 0 
    };
  }), [extern]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();
    const cExtern = getCalculatedExtern();
    const encaisse = cGros.reduce((acc, curr) => acc + curr.profit_encaisse, 0) + cExtern.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const attendu = cGros.reduce((acc, curr) => acc + curr.profit_attendu, 0);
    const pertes = cGros.reduce((acc, curr) => acc + curr.perte, 0) + cExtern.reduce((acc, curr) => acc + curr.perte, 0);
    const rev = offres.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = offres.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const totalCharges = charges.reduce((acc, curr) => acc + Number(curr.montant), 0);

    return { 
      encaisse_reel: encaisse, 
      profit_attendu: attendu, 
      pertes, 
      net_offres: rev - exp, 
      total_charges: totalCharges,
      profit_net_final: encaisse + attendu + (rev - exp) - pertes - totalCharges 
    };
  }, [getCalculatedGros, getCalculatedExtern, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, extern, offres, inventory, charges, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, updateExtern, addExtern, deleteExtern, importExtern,
      updateOffre, addOffre, deleteOffre, importOffres, updateInventory, addInventory, deleteInventory,
      updateCharge, addCharge, deleteCharge,
      getCalculatedGros, getCalculatedExtern, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useAppStore must be used within AppProvider");
  return context;
};

