        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/80 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Ref</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Vendeur</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Client</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Coût Total</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Bénéf. Vendeur</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Vente</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Status</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Profit Net</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredData.map((item) => {
                const coutTotal = Number(item.prix_achat_article) + Number(item.prix_impression);
                const profitNet = Number(item.prix_vente) - (coutTotal + Number(item.vendeur_benefice));

                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="p-2 font-mono text-xs font-black text-slate-400">
                      <EditableCell value={item.reference} onSave={(v) => updateExtern(item.id, 'reference', v)} className="text-slate-400" />
                    </td>
                    <td className="p-2">
                      <EditableCell value={item.vendeur_name} onSave={(v) => updateExtern(item.id, 'vendeur_name', v)} className="font-bold text-blue-600" />
                    </td>
                    <td className="p-2">
                      <div className="flex flex-col">
                        <EditableCell value={item.client_name} onSave={(v) => updateExtern(item.id, 'client_name', v)} className="font-bold text-slate-800" />
                        <EditableCell value={item.client_phone} onSave={(v) => updateExtern(item.id, 'client_phone', v)} className="text-[10px] text-slate-400 font-medium" />
                      </div>
                    </td>
                    <td className="p-2 text-slate-600">
                      <EditableCell type="date" value={item.date_created} onSave={(v) => updateExtern(item.id, 'date_created', v)} className="text-slate-600 font-medium" />
                    </td>
                    <td className="p-2 text-center">
                      <div className="flex items-center justify-center gap-1 text-slate-600 font-bold bg-slate-50 py-1 px-2 rounded-lg">
                         <EditableCell type="number" value={item.prix_achat_article} onSave={(v) => updateExtern(item.id, 'prix_achat_article', v)} className="w-16 text-center text-slate-500" />
                         <span className="text-[10px] text-slate-300">+</span>
                         <EditableCell type="number" value={item.prix_impression} onSave={(v) => updateExtern(item.id, 'prix_impression', v)} className="w-16 text-center text-slate-500" />
                      </div>
                    </td>
                    <td className="p-2 text-right">
                      <EditableCell type="number" value={item.vendeur_benefice} onSave={(v) => updateExtern(item.id, 'vendeur_benefice', v)} className="text-right text-purple-600 font-black" />
                    </td>
                    <td className="p-2 font-black text-slate-900 text-right">
                      <EditableCell type="number" value={item.prix_vente} onSave={(v) => updateExtern(item.id, 'prix_vente', v)} className="text-right font-black text-slate-900" />
                    </td>
                    <td className="p-2 text-center">
                      <select 
                        value={item.status} 
                        onChange={(e) => updateExtern(item.id, 'status', e.target.value)}
                        className="text-[10px] p-1.5 border-none bg-slate-100 rounded-lg cursor-pointer outline-none font-black text-slate-600 uppercase"
                      >
                        {EXTERN_STATUS_OPTIONS.map(opt => (
                          <option key={opt} value={opt}>{opt.replace(/_/g, ' ')}</option>
                        ))}
                      </select>
                    </td>
                    <td className="p-2 text-right">
                      <span className={`font-black text-sm ${item.status === ExternStatus.LIVREE ? 'text-emerald-600' : 'text-slate-400'}`}>
                        {formatPrice(profitNet)}
                      </span>
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        type="button"
                        onClick={() => { if(confirm('Supprimer cette ligne ?')) deleteExtern(item.id); }}
                        className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50"
                      >
                        <Trash2 size={16} />
                      </button>
                    </td>
                  </tr>
                );
              })}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={10} className="p-12 text-center text-slate-400">Aucune donnée trouvée pour cette période.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

