import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeExtern, Offre, InventoryItem, Charge,
  CalculatedGros, CalculatedExtern, DashboardData,
  GrosStatus, ExternStatus, OffreType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: any[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);
const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [extern, setExtern] = useState<CommandeExtern[]>(() => {
    const raw = JSON.parse(localStorage.getItem('merch_dz_extern') || JSON.stringify(INITIAL_EXTERN));
    return raw.map((i: any) => ({
      ...i,
      vendeur_name: i.vendeur_name || '',
      vendeur_benefice: i.vendeur_benefice || 0
    }));
  });
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_extern', JSON.stringify(extern));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
  }, [gros, extern, offres, inventory, charges]);

  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, extern, offres, inventory, charges, isAuthenticated]);

  useEffect(() => {
    const initFetch = async () => {
      if (!supabase || !isAuthenticated) return;
      setIsSyncing(true);
      try {
        const [gRes, eRes, oRes, iRes, cRes] = await Promise.all([
          supabase.from('gros_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('detail_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('offres_frais').select('data').eq('id', 'current_state').single(),
          supabase.from('inventory').select('data').eq('id', 'current_state').single(),
          supabase.from('les_charges').select('data').eq('id', 'current_state').single()
        ]);
        if (gRes.data?.data) setGros(gRes.data.data);
        if (eRes.data?.data) {
          const mapped = eRes.data.data.map((i: any) => ({
            ...i,
            vendeur_name: i.vendeur_name || '',
            vendeur_benefice: i.vendeur_benefice || 0
          }));
          setExtern(mapped);
        }
        if (oRes.data?.data) setOffres(oRes.data.data);
        if (iRes.data?.data) setInventory(iRes.data.data);
        if (cRes.data?.data) setCharges(cRes.data.data);
      } catch (e) { console.warn("Cloud pull failed or empty."); }
      finally { setIsSyncing(false); }
    };
    initFetch();
  }, [isAuthenticated]);

  useEffect(() => {
    const timer = setTimeout(() => { if (isAuthenticated) syncData(); }, 10000);
    return () => clearTimeout(timer);
  }, [gros, extern, offres, inventory, charges, syncData, isAuthenticated]);

  const login = (password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  };

  // Updaters
  const updateGros = (id: string, field: keyof CommandeGros, value: any) => setGros(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addGros = () => setGros(p => [...p, { id: generateId(), reference: `G${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' }]);
  const deleteGros = (id: string) => setGros(prev => prev.filter(i => i.id !== id));
  const importGros = (data: any[]) => setGros(data.map(i => ({ ...i, id: i.id || generateId() })));

  const updateExtern = (id: string, field: keyof CommandeExtern, value: any) => setExtern(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addExtern = () => setExtern(p => [...p, { id: generateId(), reference: `SIT-${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: ExternStatus.EN_PRODUCTION, stock_note: '', vendeur_name: '', vendeur_benefice: 0 }]);
  const deleteExtern = (id: string) => setExtern(prev => prev.filter(i => i.id !== id));
  const importExtern = (data: any[]) => setExtern(data.map(i => ({ ...i, id: i.id || generateId(), vendeur_name: i.vendeur_name || '', vendeur_benefice: i.vendeur_benefice || 0 })));

  const updateOffre = (id: string, field: keyof Offre, value: any) => setOffres(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addOffre = () => setOffres(p => [...p, { id: generateId(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }]);
  const deleteOffre = (id: string) => setOffres(prev => prev.filter(i => i.id !== id));
  const importOffres = (data: any[]) => setOffres(data.map(i => ({ ...i, id: i.id || generateId() })));

  const updateInventory = (id: string, field: keyof InventoryItem, value: any) => setInventory(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addInventory = () => setInventory(p => [...p, { id: generateId(), name: 'Nouveau Stock', sku: 'SKU-'+p.length, quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }]);
  const deleteInventory = (id: string) => setInventory(prev => prev.filter(i => i.id !== id));

  const updateCharge = (id: string, field: keyof Charge, value: any) => setCharges(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
  const addCharge = (label: string = 'Autre') => setCharges(p => [...p, { id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }]);
  const deleteCharge = (id: string) => setCharges(prev => prev.filter(i => i.id !== id));

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { ...i, cost, profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, perte: i.status === GrosStatus.RETOUR ? cost : 0 };
  }), [gros]);

  const getCalculatedExtern = useCallback((): CalculatedExtern[] => extern.map(i => {
    // Coût Total = Achat + Impression
    const raw_cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    // Profit = Vente - (Coût Total + Bénéfice Vendeur)
    const profit = Number(i.prix_vente) - (raw_cost + Number(i.vendeur_benefice));

    return { 
      ...i, 
      cost: raw_cost, 
      profit_reel: i.status === ExternStatus.LIVREE ? profit : 0, 
      perte: i.status === ExternStatus.RETOUR ? raw_cost : 0 
    };
  }), [extern]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();
    const cExtern = getCalculatedExtern();
    const encaisse = cGros.reduce((acc, curr) => acc + curr.profit_encaisse, 0) + cExtern.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const attendu = cGros.reduce((acc, curr) => acc + curr.profit_attendu, 0);
    const pertes = cGros.reduce((acc, curr) => acc + curr.perte, 0) + cExtern.reduce((acc, curr) => acc + curr.perte, 0);
    const rev = offres.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = offres.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const totalCharges = charges.reduce((acc, curr) => acc + Number(curr.montant), 0);

    return { 
      encaisse_reel: encaisse, 
      profit_attendu: attendu, 
      pertes, 
      net_offres: rev - exp, 
      total_charges: totalCharges,
      profit_net_final: encaisse + attendu + (rev - exp) - pertes - totalCharges 
    };
  }, [getCalculatedGros, getCalculatedExtern, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, extern, offres, inventory, charges, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, updateExtern, addExtern, deleteExtern, importExtern,
      updateOffre, addOffre, deleteOffre, importOffres, updateInventory, addInventory, deleteInventory,
      updateCharge, addCharge, deleteCharge,
      getCalculatedGros, getCalculatedExtern, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useAppStore must be used within AppProvider");
  return context;
};

import React, { useRef, useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { EXTERN_STATUS_OPTIONS } from '../constants.ts';
import { ExternStatus } from '../types.ts';
import { Plus, Download, Upload, Trash2, Search, Filter, ShoppingBag, Banknote, History, Calendar, User, Globe, AlertCircle, TrendingDown } from 'lucide-react';

const CommandesDetail: React.FC = () => {
  const { getCalculatedExtern, updateExtern, addExtern, deleteExtern, importExtern } = useAppStore();
  const allData = getCalculatedExtern();
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchesSearch = item.client_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          item.reference.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          (item.vendeur_name || '').toLowerCase().includes(searchTerm.toLowerCase());

      const itemDate = item.date_created;
      const matchesStart = !dateStart || itemDate >= dateStart;
      const matchesEnd = !dateEnd || itemDate <= dateEnd;

      return matchesSearch && matchesStart && matchesEnd;
    }).sort((a, b) => new Date(b.date_created).getTime() - new Date(a.date_created).getTime());
  }, [allData, searchTerm, dateStart, dateEnd]);

  const stats = useMemo(() => {
    const totalProfit = filteredData.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const totalVendorBenefice = filteredData.reduce((acc, curr) => acc + (curr.status === ExternStatus.LIVREE ? Number(curr.vendeur_benefice) : 0), 0);
    const deliveredCount = filteredData.filter(d => d.status === ExternStatus.LIVREE).length;
    // Loss is the sum of (Achat + Impression) for RETOUR status
    const totalLoss = filteredData.reduce((acc, curr) => acc + curr.perte, 0);

    return { totalProfit, totalVendorBenefice, deliveredCount, totalLoss };
  }, [filteredData]);

  const formatPrice = (val: number) => {
    return val.toLocaleString('fr-DZ') + ' DA';
  };

  const resetFilters = () => {
    setSearchTerm('');
    setDateStart('');
    setDateEnd('');
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());

      const importedData = lines.slice(1)
        .filter(line => line.trim())
        .map(line => {
          const values = line.split(',').map(v => v.trim());
          const obj: any = {};
          headers.forEach((header, index) => {
            const val = values[index];
            if (header.includes('prix') || header.includes('achat') || header.includes('vente') || header.includes('montant') || header.includes('coût') || header.includes('vendeur_benefice')) {
              obj[header] = Number(val) || 0;
            } else if (header === 'impression') {
              obj[header] = val.toLowerCase() === 'true' || val === '1';
            } else {
              obj[header] = val;
            }
          });

          return {
            reference: obj.reference || obj.ref || 'SIT-NEW',
            client_name: obj.client_name || obj.client || '',
            client_phone: obj.client_phone || obj.contact || '',
            vendeur_name: obj.vendeur_name || obj.vendeur || '',
            vendeur_benefice: obj.vendeur_benefice || 0,
            date_created: obj.date_created || obj.date || new Date().toISOString().split('T')[0],
            prix_achat_article: obj.prix_achat_article || obj.achat || 0,
            impression: obj.impression ?? false,
            prix_impression: obj.prix_impression || 0,
            prix_vente: obj.prix_vente || obj.vente || 0,
            status: (obj.status as ExternStatus) || ExternStatus.EN_PRODUCTION,
            stock_note: obj.stock_note || obj.note || ''
          };
        });

      importExtern(importedData);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const exportCSV = () => {
    if (filteredData.length === 0) return;
    const headers = ["reference", "vendeur_name", "vendeur_benefice", "client_name", "client_phone", "date_created", "prix_achat_article", "prix_impression", "prix_vente", "status", "stock_note"];
    const rows = filteredData.map(item => [
      item.reference,
      item.vendeur_name,
      item.vendeur_benefice,
      item.client_name,
      item.client_phone,
      item.date_created,
      item.prix_achat_article,
      item.prix_impression,
      item.prix_vente,
      item.status,
      item.stock_note
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n"
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "commandes_sitweb.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (confirm('Supprimer cette ligne ?')) {
      deleteExtern(id);
    }
