const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: any[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);
const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [extern, setExtern] = useState<CommandeExtern[]>(() => {
    const raw = JSON.parse(localStorage.getItem('merch_dz_extern') || JSON.stringify(INITIAL_EXTERN));
    return raw.map((i: any) => ({
      ...i,
      vendeur_name: i.vendeur_name || '',
      vendeur_benefice: i.vendeur_benefice || 0
    }));
  });
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_extern', JSON.stringify(extern));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
  }, [gros, extern, offres, inventory, charges]);

  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, extern, offres, inventory, charges, isAuthenticated]);

  useEffect(() => {
    const initFetch = async () => {
      if (!supabase || !isAuthenticated) return;
      setIsSyncing(true);
      try {
        const [gRes, eRes, oRes, iRes, cRes] = await Promise.all([
          supabase.from('gros_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('detail_orders').select('data').eq('id', 'current_state').single(),
          supabase.from('offres_frais').select('data').eq('id', 'current_state').single(),
          supabase.from('inventory').select('data').eq('id', 'current_state').single(),
          supabase.from('les_charges').select('data').eq('id', 'current_state').single()
        ]);
        if (gRes.data?.data) setGros(gRes.data.data);
        if (eRes.data?.data) {
          const mapped = eRes.data.data.map((i: any) => ({
            ...i,
            vendeur_name: i.vendeur_name || '',
            vendeur_benefice: i.vendeur_benefice || 0
          }));
          setExtern(mapped);
        }
        if (oRes.data?.data) setOffres(oRes.data.data);
        if (iRes.data?.data) setInventory(iRes.data.data);
        if (cRes.data?.data) setCharges(cRes.data.data);
      } catch (e) { console.warn("Cloud pull failed or empty."); }
      finally { setIsSyncing(false); }
    };
    initFetch();
  }, [isAuthenticated]);

  useEffect(() => {
    const timer = setTimeout(() => { if (isAuthenticated) syncData(); }, 10000);
    return () => clearTimeout(timer);
  }, [gros, extern, offres, inventory, charges, syncData, isAuthenticated]);

  const login = (password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  };

  // Updaters
  const updateGros = (id: string, field: keyof CommandeGros, value: any) => setGros(prev => prev.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
  const addGros = () => setGros(p => [...p, { id: generateId(), reference: `G${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' }]);
  const deleteGros = (id: string) => setGros(prev => prev.filter(i => String(i.id) !== String(id)));
  const importGros = (data: any[]) => setGros(data.map(i => ({ ...i, id: i.id || generateId() })));

  const updateExtern = (id: string, field: keyof CommandeExtern, value: any) => setExtern(prev => prev.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
  const addExtern = () => setExtern(p => [...p, { id: generateId(), reference: `SIT-${p.length+1}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: ExternStatus.EN_PRODUCTION, stock_note: '', vendeur_name: '', vendeur_benefice: 0 }]);
  const deleteExtern = (id: string) => setExtern(prev => prev.filter(i => String(i.id) !== String(id)));
  const importExtern = (data: any[]) => setExtern(data.map(i => ({ ...i, id: i.id || generateId(), vendeur_name: i.vendeur_name || '', vendeur_benefice: i.vendeur_benefice || 0 })));

  const updateOffre = (id: string, field: keyof Offre, value: any) => setOffres(prev => prev.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
  const addOffre = () => setOffres(p => [...p, { id: generateId(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }]);
  const deleteOffre = (id: string) => setOffres(prev => prev.filter(i => String(i.id) !== String(id)));
  const importOffres = (data: any[]) => setOffres(data.map(i => ({ ...i, id: i.id || generateId() })));

  const updateInventory = (id: string, field: keyof InventoryItem, value: any) => setInventory(prev => prev.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
  const addInventory = () => setInventory(p => [...p, { id: generateId(), name: 'Nouveau Stock', sku: 'SKU-'+p.length, quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }]);
  const deleteInventory = (id: string) => setInventory(prev => prev.filter(i => String(i.id) !== String(id)));

  const updateCharge = (id: string, field: keyof Charge, value: any) => setCharges(prev => prev.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
  const addCharge = (label: string = 'Autre') => setCharges(p => [...p, { id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }]);
  const deleteCharge = (id: string) => setCharges(prev => prev.filter(i => String(i.id) !== String(id)));

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { ...i, cost, profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, perte: i.status === GrosStatus.RETOUR ? cost : 0 };
  }), [gros]);

  const getCalculatedExtern = useCallback((): CalculatedExtern[] => extern.map(i => {
    const raw_cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - (raw_cost + Number(i.vendeur_benefice));
    return { 
      ...i, 
      cost: raw_cost, 
      profit_reel: i.status === ExternStatus.LIVREE ? profit : 0, 
      perte: i.status === ExternStatus.RETOUR ? raw_cost : 0 
    };
  }), [extern]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();
    const cExtern = getCalculatedExtern();
    const encaisse = cGros.reduce((acc, curr) => acc + curr.profit_encaisse, 0) + cExtern.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const attendu = cGros.reduce((acc, curr) => acc + curr.profit_attendu, 0);
    const pertes = cGros.reduce((acc, curr) => acc + curr.perte, 0) + cExtern.reduce((acc, curr) => acc + curr.perte, 0);
    const rev = offres.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = offres.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const totalCharges = charges.reduce((acc, curr) => acc + Number(curr.montant), 0);

    return { 
      encaisse_reel: encaisse, 
      profit_attendu: attendu, 
      pertes, 
      net_offres: rev - exp, 
      total_charges: totalCharges,
      profit_net_final: encaisse + attendu + (rev - exp) - pertes - totalCharges 
    };
  }, [getCalculatedGros, getCalculatedExtern, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, extern, offres, inventory, charges, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, updateExtern, addExtern, deleteExtern, importExtern,
      updateOffre, addOffre, deleteOffre, importOffres, updateInventory, addInventory, deleteInventory,
      updateCharge, addCharge, deleteCharge,
      getCalculatedGros, getCalculatedExtern, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useAppStore must be used within AppProvider");
  return context;
};

import React, { useRef, useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { OFFRE_TYPE_OPTIONS, OFFRE_CATEGORY_OPTIONS } from '../constants.ts';
import { OffreType, OffreCategory } from '../types.ts';
import { Plus, TrendingUp, TrendingDown, Download, Upload, Trash2, Search, Zap, Calendar } from 'lucide-react';

const Offres: React.FC = () => {
  const { offres, updateOffre, addOffre, deleteOffre, importOffres } = useAppStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredData = useMemo(() => {
    return offres.filter(item => {
      const matchesSearch = item.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          item.category.toLowerCase().includes(searchTerm.toLowerCase());

      const itemDate = item.date;
      const matchesStart = !dateStart || itemDate >= dateStart;
      const matchesEnd = !dateEnd || itemDate <= dateEnd;

      return matchesSearch && matchesStart && matchesEnd;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [offres, searchTerm, dateStart, dateEnd]);

  const stats = useMemo(() => {
    const rev = filteredData.filter(o => o.type === OffreType.REVENUE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    const exp = filteredData.filter(o => o.type === OffreType.EXPENSE).reduce((acc, curr) => acc + Number(curr.montant), 0);
    return { rev, exp, net: rev - exp };
  }, [filteredData]);

  const formatPrice = (val: number) => {
    return val.toLocaleString('fr-DZ') + ' DA';
  };

  const resetFilters = () => {
    setSearchTerm('');
    setDateStart('');
    setDateEnd('');
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (confirm('Voulez-vous vraiment supprimer cet enregistrement ?')) {
      deleteOffre(id);
    }
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());

      const importedData = lines.slice(1)
        .filter(line => line.trim())
        .map(line => {
          const values = line.split(',').map(v => v.trim());
          const obj: any = {};
          headers.forEach((header, index) => {
            const val = values[index];
            if (header.includes('montant') || header.includes('amount') || header.includes('prix')) {
              obj[header] = Number(val) || 0;
            } else {
              obj[header] = val;
            }
          });

          return {
            date: obj.date || new Date().toISOString().split('T')[0],
            type: (obj.type as OffreType) || OffreType.EXPENSE,
            category: (obj.category as OffreCategory) || OffreCategory.OTHER,
            description: obj.description || '',
            montant: obj.montant || obj.amount || 0
          };
        });

      importOffres(importedData);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const exportCSV = () => {
    if (filteredData.length === 0) return;
    const headers = ["date", "type", "category", "description", "montant"];
    const rows = filteredData.map(item => [
      item.date,
      item.type,
      item.category,
      item.description,
      item.montant
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n"
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "offres_et_frais.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Offres & Frais Globaux</h2>
          <p className="text-slate-500 text-sm">Gestion des revenus et dépenses opérationnelles indirectes.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportCSV} 
            accept=".csv" 
            className="hidden" 
          />
          <button 
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50"
          >
            <Upload size={16} /> Importer
          </button>
          <button 
            type="button"
            onClick={exportCSV}
            className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50"
          >
            <Download size={16} /> Exporter
          </button>
          <button 
            type="button"
            onClick={addOffre}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 shadow-md transition-all"
          >
            <Plus size={16} /> Nouveau Flux
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard label="Revenus (Période)" value={formatPrice(stats.rev)} icon={TrendingUp} color="text-emerald-600" bg="bg-emerald-50" />
        <StatCard label="Dépenses (Période)" value={formatPrice(stats.exp)} icon={TrendingDown} color="text-orange-600" bg="bg-orange-50" />
        <StatCard label="Bilan (Période)" value={formatPrice(stats.net)} icon={Zap} color="text-slate-600" bg="bg-slate-50" />
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Filtrer par description ou catégorie..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all text-sm"
            />
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-3 py-1.5 shadow-sm">
              <Calendar size={14} className="text-slate-400" />
              <input 
                type="date" 
                value={dateStart} 
                onChange={(e) => setDateStart(e.target.value)}
                className="text-xs outline-none bg-transparent font-medium text-slate-700"
              />
              <span className="text-slate-300">à</span>
              <input 
                type="date" 
                value={dateEnd} 
                onChange={(e) => setDateEnd(e.target.value)}
                className="text-xs outline-none bg-transparent font-medium text-slate-700"
              />
            </div>
            {(searchTerm || dateStart || dateEnd) && (
              <button 
                onClick={resetFilters}
                className="text-xs font-bold text-blue-600 hover:text-blue-700 transition-colors"
              >
                Réinitialiser
              </button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/80 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Type</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Catégorie</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Description</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Montant</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredData.map((item) => (
                <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="p-2">
                    <EditableCell type="date" value={item.date} onSave={(v) => updateOffre(item.id, 'date', v)} className="text-slate-500 font-medium" />
                  </td>
                  <td className="p-2">
                    <div className="flex items-center gap-2">
                      <select 
                        value={item.type} 
                        onChange={(e) => updateOffre(item.id, 'type', e.target.value)}
                        className={`text-[10px] px-2 py-1 border-none rounded-lg font-black uppercase tracking-widest cursor-pointer ${item.type === 'revenue' ? 'bg-emerald-50 text-emerald-700' : 'bg-orange-50 text-orange-700'}`}
                      >
                        {OFFRE_TYPE_OPTIONS.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    </div>
                  </td>
                  <td className="p-2">
                    <select 
                      value={item.category} 
                      onChange={(e) => updateOffre(item.id, 'category', e.target.value)}
                      className="text-[10px] p-1.5 border-none bg-slate-100 rounded-lg text-slate-600 font-bold uppercase tracking-tight"
                    >
                      {OFFRE_CATEGORY_OPTIONS.map(opt => (
                        <option key={opt} value={opt}>{opt.toUpperCase()}</option>
                      ))}
                    </select>
                  </td>
                  <td className="p-2">
                    <EditableCell value={item.description} onSave={(v) => updateOffre(item.id, 'description', v)} className="min-w-[200px] text-slate-700 font-medium" />
                  </td>
                  <td className="p-2 text-right">
                    <EditableCell 
                      type="number" 
                      value={item.montant} 
                      onSave={(v) => updateOffre(item.id, 'montant', v)} 
                      className={`text-right font-black ${item.type === 'revenue' ? 'text-emerald-600' : 'text-orange-600'}`} 
                    />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      onClick={(e) => handleDelete(e, item.id)}
                      className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50"
                    >
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={6} className="p-12 text-center text-slate-400">Aucun mouvement trouvé pour cette période.</td>
                </tr>
              )}
