                  <td className="p-2"><EditableCell value={item.sku} onSave={v => updateInventory(item.id, 'sku', v)} className="font-mono text-xs text-slate-500" /></td>
                  <td className="p-2 font-black text-right text-slate-700">
                    <EditableCell type="number" value={item.quantity} onSave={v => updateInventory(item.id, 'quantity', v)} className={`text-right ${item.quantity <= item.min_stock ? 'text-red-600' : ''}`} />
                  </td>
                  <td className="p-2 text-right"><EditableCell type="number" value={item.min_stock} onSave={v => updateInventory(item.id, 'min_stock', v)} className="text-slate-400 text-right" /></td>
                  <td className="p-2 font-bold text-slate-600 text-right"><EditableCell type="number" value={item.unit_cost} onSave={v => updateInventory(item.id, 'unit_cost', v)} className="text-right" /></td>
                  <td className="p-2"><EditableCell value={item.supplier} onSave={v => updateInventory(item.id, 'supplier', v)} className="text-slate-500 italic text-xs" /></td>
                  <td className="p-2 text-center">
                    <button type="button" onClick={(e) => handleDelete(e, item.id)} className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50">
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

