import React, { useRef, useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { Plus, Search, Wallet, UserCheck, Briefcase, Trash2, Download, Upload } from 'lucide-react';

const PRESET_LABELS = [
  'Salaire Billel',
  'Salaire Oussama',
  'Salaire Ahmed',
  'Salaire Assistante',
  'Transport',
  'Service online',
  'Autre',
  'salaire teleoperatrice',
  'locale',
  'investiseur salaise'
];

const Charges: React.FC = () => {
  const { charges, updateCharge, addCharge, deleteCharge, importCharges } = useAppStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredData = useMemo(() => {
    return charges.filter(item => {
      const matchesSearch = item.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          item.note.toLowerCase().includes(searchTerm.toLowerCase());
      const itemDate = item.date;
      const matchesStart = !dateStart || itemDate >= dateStart;
      const matchesEnd = !dateEnd || itemDate <= dateEnd;
      return matchesSearch && matchesStart && matchesEnd;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [charges, searchTerm, dateStart, dateEnd]);

  const stats = useMemo(() => {
    const total = filteredData.reduce((acc, curr) => acc + Number(curr.montant), 0);
    const count = filteredData.length;
    const avg = count > 0 ? total / count : 0;
    return { total, count, avg };
  }, [filteredData]);

  const formatPrice = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('Voulez-vous supprimer cette charge du grand livre ?')) {
      deleteCharge(id);
    }
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
      const importedData = lines.slice(1).filter(line => line.trim()).map(line => {
        const values = line.split(',').map(v => v.trim());
        const obj: any = {};
        headers.forEach((header, index) => { obj[header] = values[index]; });
        return {
          date: obj.date || new Date().toISOString().split('T')[0],
          label: obj.label || obj.title || 'Nouvelle Charge',
          note: obj.note || obj.details || '',
          montant: Number(obj.montant) || Number(obj.amount) || 0
        };
      });
      importCharges(importedData);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const exportCSV = () => {
    if (filteredData.length === 0) return;
    const headers = ["date", "label", "note", "montant"];
    const rows = filteredData.map(item => [item.date, item.label, item.note, item.montant]);
    const csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", "les_charges.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-10">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Les Charges</h2>
          <p className="text-slate-500 text-sm">Gestion des salaires, loyers et charges fixes.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <input type="file" ref={fileInputRef} onChange={handleImportCSV} accept=".csv" className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50">
            <Upload size={16} /> Importer
          </button>
          <button onClick={exportCSV} className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50">
            <Download size={16} /> Exporter
          </button>
          <div className="relative group">
            <button type="button" className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95">
              <Plus size={16} /> Ajouter une Charge
            </button>
            <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 p-2 text-left">
              <p className="px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 mb-1 text-left">Presets</p>
              {PRESET_LABELS.map(label => (
                <button key={label} type="button" onClick={() => addCharge(label)} className="w-full text-left px-3 py-2 hover:bg-blue-50 rounded-xl text-xs font-bold text-slate-600 hover:text-blue-600 transition-colors">
                  {label}
                </button>
              ))}
              <button type="button" onClick={() => addCharge('Nouvelle Charge')} className="w-full text-left px-3 py-2 mt-1 bg-slate-50 hover:bg-slate-100 rounded-xl text-xs font-black text-slate-400 text-center uppercase tracking-widest">
                + Libre
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard label="Total Charges (Période)" value={formatPrice(stats.total)} icon={Wallet} color="text-orange-600" bg="bg-orange-50" />
        <StatCard label="Nombre d'Entrées" value={stats.count} icon={Briefcase} color="text-blue-600" bg="bg-blue-50" />
        <StatCard label="Moyenne / Entrée" value={formatPrice(stats.avg)} icon={UserCheck} color="text-slate-600" bg="bg-slate-50" />
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-col lg:flex-row lg:items-center gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" placeholder="Rechercher par label ou note..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all text-sm font-medium" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Libellé</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Note / Détails</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Montant (DA)</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredData.map((item) => (
                <tr key={item.id} className="hover:bg-orange-50/30 transition-colors group">
                  <td className="p-2"><EditableCell type="date" value={item.date} onSave={(v) => updateCharge(item.id, 'date', v)} className="text-slate-600 font-medium" /></td>
                  <td className="p-2"><EditableCell value={item.label} onSave={(v) => updateCharge(item.id, 'label', v)} className="font-black text-slate-800" /></td>
                  <td className="p-2 text-slate-500"><EditableCell value={item.note} onSave={(v) => updateCharge(item.id, 'note', v)} className="text-slate-500 italic text-xs" /></td>
                  <td className="p-2 text-right font-black text-orange-600"><EditableCell type="number" value={item.montant} onSave={(v) => updateCharge(item.id, 'montant', v)} className="text-right" /></td>
                  <td className="p-2 text-center">
                    <button type="button" onClick={(e) => handleDelete(e, item.id)} className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50">
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Charges;

import React, { useMemo, useState } from 'react';
import { useAppStore } from '../store.tsx';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Clock, AlertCircle, Banknote, Calendar, Wallet, TrendingUp, Truck } from 'lucide-react';
import { GrosStatus, ExternStatus, OffreType } from '../types.ts';

const Dashboard: React.FC = () => {
  const { getDashboardData, getCalculatedGros, getCalculatedExtern, offres, charges } = useAppStore();
  const data = getDashboardData();
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const formatCurrency = (val: number) => {
    return val.toLocaleString('fr-DZ') + ' DA';
  };

  // Aggregate daily performance data
  const chartData = useMemo(() => {
    const dailyMap: Record<string, number> = {};

    // 1. Gros Profits
    getCalculatedGros().forEach(item => {
      const d = item.date_created;
      const profit = item.prix_vente - item.cost;
      dailyMap[d] = (dailyMap[d] || 0) + profit;
    });

    // 2. Extern Profits
    getCalculatedExtern().forEach(item => {
      const d = item.date_created;
      const profit = Number(item.prix_vente) - (item.cost + Number(item.vendeur_benefice));
      dailyMap[d] = (dailyMap[d] || 0) + profit;
    });

    // 3. Offres
    offres.forEach(item => {
      const d = item.date;
      const val = item.type === OffreType.REVENUE ? Number(item.montant) : -Number(item.montant);
      dailyMap[d] = (dailyMap[d] || 0) + val;
    });

    // 4. Charges
    charges.forEach(item => {
      const d = item.date;
      dailyMap[d] = (dailyMap[d] || 0) - Number(item.montant);
    });

    // Convert to array and filter by date range
    const sortedDates = Object.keys(dailyMap).sort();
    let results = sortedDates.map(date => ({
      date,
      profit: dailyMap[date],
      formattedDate: new Date(date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' })
    }));

    if (dateStart) results = results.filter(r => r.date >= dateStart);
    if (dateEnd) results = results.filter(r => r.date <= dateEnd);

    // If no data, return empty array
    return results.length > 0 ? results : [{ date: '', profit: 0, formattedDate: '' }];
  }, [getCalculatedGros, getCalculatedExtern, offres, charges, dateStart, dateEnd]);

  const kpis = [
    { label: 'Encaisse Réel', value: data.encaisse_reel, icon: Banknote, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'Profit Attendu', value: data.profit_attendu, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Pertes (Retours)', value: data.pertes, icon: AlertCircle, color: 'text-red-600', bg: 'bg-red-50' },
    { label: 'Les Charges', value: data.total_charges, icon: Wallet, color: 'text-orange-600', bg: 'bg-orange-50' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Synthèse financière et opérationnelle globale.</p>
        </div>

        <div className="flex items-center gap-4 bg-white p-2 rounded-2xl border border-slate-200 shadow-sm self-start">
          <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
            <Calendar size={16} className="text-blue-500" />
            <input 
              type="date" 
              value={dateStart}
              onChange={(e) => setDateStart(e.target.value)}
              className="bg-transparent text-xs font-bold outline-none text-slate-700"
            />
            <span className="text-xs text-slate-300 font-bold">à</span>
            <input 
              type="date" 
              value={dateEnd}
              onChange={(e) => setDateEnd(e.target.value)}
              className="bg-transparent text-xs font-bold outline-none text-slate-700"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md">
            <div className={`w-12 h-12 rounded-2xl ${kpi.bg} flex items-center justify-center mb-6`}>
              <kpi.icon className={kpi.color} size={24} />
            </div>
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{kpi.label}</p>
            <h3 className="text-2xl font-black text-slate-900">{formatCurrency(kpi.value)}</h3>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h4 className="font-bold text-slate-800 text-lg">Performance Analytique</h4>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">Bilan Quotidien Net</span>
          </div>

          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="formattedDate" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }}
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }}
                  tickFormatter={(val) => `${(val / 1000).toFixed(0)}k`}
                />
                <Tooltip 
                  contentStyle={{ 
                    borderRadius: '16px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                    fontSize: '12px',
                    fontWeight: 'bold',
                    padding: '12px'
                  }}
                  formatter={(value: number) => [formatCurrency(value), 'Profit Net']}
                  labelStyle={{ color: '#64748b', marginBottom: '4px' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="profit" 
                  stroke="#3b82f6" 
                  strokeWidth={3}
                  fillOpacity={1} 
                  fill="url(#colorProfit)" 
                  animationDuration={1500}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-900 text-white p-8 rounded-3xl shadow-xl shadow-slate-200 relative overflow-hidden flex flex-col justify-between">
          <div className="relative z-10">
            <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-4">Solde Net Final</p>
            <h4 className="text-4xl font-black mb-4 tracking-tighter">
              {formatCurrency(data.profit_net_final)}
            </h4>
            <p className="text-slate-400 text-sm font-medium leading-relaxed">
              Calcul final après déduction des pertes, charges opérationnelles et investissements marketing.
            </p>
          </div>
          <div className="relative z-10 space-y-3 mt-12">
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">Flux Offres Net</span>
               <span className={`text-xs font-black ${data.net_offres >= 0 ? 'text-emerald-400' : 'text-orange-400'}`}>
                 {formatCurrency(data.net_offres)}
               </span>
            </div>
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">Ratio Charges/Profit</span>
               <span className="text-xs font-black text-slate-300">
                 {data.encaisse_reel > 0 ? ((data.total_charges / (data.encaisse_reel + data.profit_attendu)) * 100).toFixed(1) : 0}%
               </span>
            </div>
          </div>
          <TrendingUp size={150} className="absolute -bottom-10 -right-10 text-white/5 rotate-12" />
        </div>
      </div>
    </div>
  );
};

