  GrosStatus, ExternStatus, OffreType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  extern: CommandeExtern[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateExtern: (id: string, field: keyof CommandeExtern, value: any) => void;
  addExtern: () => void;
  deleteExtern: (id: string) => void;
  importExtern: (data: any[]) => void;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  importInventory: (data: any[]) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  importCharges: (data: any[]) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedExtern: () => CalculatedExtern[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);
const ADMIN_PASSWORD = (window as any).process?.env?.APP_PASSWORD || "merchdz_private_2025";

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('merch_dz_auth') === 'true');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [extern, setExtern] = useState<CommandeExtern[]>(() => JSON.parse(localStorage.getItem('merch_dz_extern') || JSON.stringify(INITIAL_EXTERN)));
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_extern', JSON.stringify(extern));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
  }, [gros, extern, offres, inventory, charges]);

  const syncData = useCallback(async () => {
    if (!supabase || !isAuthenticated) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('detail_orders').upsert({ id: 'current_state', data: extern }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, extern, offres, inventory, charges, isAuthenticated]);

  const login = useCallback((password: string) => {
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
      localStorage.setItem('merch_dz_auth', 'true');
      return true;
    }
    return false;
  }, []);

  const logout = useCallback(() => {
    setIsAuthenticated(false);
    localStorage.removeItem('merch_dz_auth');
  }, []);

  const updateGros = useCallback((id: string, field: keyof CommandeGros, value: any) => 
    setGros(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addGros = useCallback(() => 
    setGros(p => [{ id: generateId(), reference: `G${Date.now()}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' }, ...p]), []);

  const deleteGros = useCallback((id: string) => {
    setGros(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const importGros = useCallback((data: any[]) => {
    const formatted = data.map(item => ({ ...item, id: generateId() }));
    setGros(prev => [...formatted, ...prev]);
  }, []);

  const updateExtern = useCallback((id: string, field: keyof CommandeExtern, value: any) => 
    setExtern(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addExtern = useCallback(() => 
    setExtern(p => [{ id: generateId(), reference: String(Date.now()).slice(-4), date_created: new Date().toISOString().split('T')[0], cout_production: 0, prix_vente: 0, status: ExternStatus.LIVREE_NON_ENCAISSE, stock_note: '', vendeur_name: 'V-X', vendeur_benefice: 0 }, ...p]), []);

  const deleteExtern = useCallback((id: string) => {
    setExtern(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const importExtern = useCallback((data: any[]) => {
    const formatted = data.map(item => ({ ...item, id: generateId() }));
    setExtern(prev => [...formatted, ...prev]);
  }, []);

  const updateOffre = useCallback((id: string, field: keyof Offre, value: any) => 
    setOffres(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addOffre = useCallback(() => 
    setOffres(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }, ...p]), []);

  const deleteOffre = useCallback((id: string) => {
    setOffres(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const importOffres = useCallback((data: any[]) => {
    const formatted = data.map(item => ({ ...item, id: generateId() }));
    setOffres(prev => [...formatted, ...prev]);
  }, []);

  const updateInventory = useCallback((id: string, field: keyof InventoryItem, value: any) => 
    setInventory(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addInventory = useCallback(() => 
    setInventory(p => [{ id: generateId(), name: 'Nouveau Stock', sku: 'SKU-'+Date.now(), quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }, ...p]), []);

  const deleteInventory = useCallback((id: string) => {
    setInventory(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const importInventory = useCallback((data: any[]) => {
    const formatted = data.map(item => ({ ...item, id: generateId() }));
    setInventory(prev => [...formatted, ...prev]);
  }, []);

  const updateCharge = useCallback((id: string, field: keyof Charge, value: any) => 
    setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addCharge = useCallback((label: string = 'Autre') => 
    setCharges(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }, ...p]), []);

  const deleteCharge = useCallback((id: string) => {
    setCharges(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const importCharges = useCallback((data: any[]) => {
    const formatted = data.map(item => ({ ...item, id: generateId() }));
    setCharges(prev => [...formatted, ...prev]);
  }, []);

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { ...i, cost, profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, perte: i.status === GrosStatus.RETOUR ? cost : 0 };
  }), [gros]);

  const getCalculatedExtern = useCallback((): CalculatedExtern[] => extern.map(i => {
    const profit = Number(i.prix_vente) - (Number(i.cout_production) + Number(i.vendeur_benefice));
    return { 
      ...i, 
      profit_reel: i.status === ExternStatus.LIVREE_ENCAISSE ? profit : 0, 
      profit_attendu: i.status === ExternStatus.LIVREE_NON_ENCAISSE ? profit : 0,
      perte: i.status === ExternStatus.RETOUR ? Number(i.cout_production) : 0 
    };
  }), [extern]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();
    const cExtern = getCalculatedExtern();

    const encaisse = cGros.reduce((a, c) => a + c.profit_encaisse, 0) + cExtern.reduce((a, c) => a + c.profit_reel, 0);
    const attendu = cGros.reduce((a, c) => a + c.profit_attendu, 0) + cExtern.reduce((a, c) => a + c.profit_attendu, 0);
    const pertes = cGros.reduce((a, c) => a + c.perte, 0) + cExtern.reduce((a, c) => a + c.perte, 0);

    const net_offres = offres.reduce((a, c) => c.type === OffreType.REVENUE ? a + Number(c.montant) : a - Number(c.montant), 0);
    const total_charges = charges.reduce((a, c) => a + Number(c.montant), 0);

    return { encaisse_reel: encaisse, profit_attendu: attendu, pertes, net_offres, total_charges, profit_net_final: encaisse + attendu + net_offres - pertes - total_charges };
  }, [getCalculatedGros, getCalculatedExtern, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, extern, offres, inventory, charges, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, 
      updateExtern, addExtern, deleteExtern, importExtern,
      updateOffre, addOffre, deleteOffre, importOffres, 
      updateInventory, addInventory, deleteInventory, importInventory,
      updateCharge, addCharge, deleteCharge, importCharges,
      getCalculatedGros, getCalculatedExtern, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("Store context mismatch");
  return context;
};

import React, { useRef, useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { EXTERN_STATUS_OPTIONS } from '../constants.ts';
import { ExternStatus } from '../types.ts';
import { Plus, Search, Banknote, User, Trash2, Download, Upload, AlertCircle, Clock } from 'lucide-react';

const CommandesDetail: React.FC = () => {
  const { getCalculatedExtern, updateExtern, addExtern, deleteExtern, importExtern } = useAppStore();
  const allData = getCalculatedExtern();
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      return (item.reference || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
             (item.vendeur_name || '').toLowerCase().includes(searchTerm.toLowerCase());
    }).sort((a, b) => new Date(b.date_created).getTime() - new Date(a.date_created).getTime());
  }, [allData, searchTerm]);

  const stats = useMemo(() => {
    const profitReel = filteredData.reduce((acc, curr) => acc + curr.profit_reel, 0);
    const profitAttendu = filteredData.reduce((acc, curr) => acc + curr.profit_attendu, 0);
    const pertesTotal = filteredData.reduce((acc, curr) => acc + curr.perte, 0);
    const totalVendorBenefice = filteredData.reduce((acc, curr) => acc + (curr.status === ExternStatus.LIVREE_ENCAISSE ? Number(curr.vendeur_benefice) : 0), 0);
    return { profitReel, profitAttendu, pertesTotal, totalVendorBenefice };
  }, [filteredData]);

  const formatPrice = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('Voulez-vous vraiment supprimer cet enregistrement de commande sitweb ?')) {
      deleteExtern(id);
    }
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
      const importedData = lines.slice(1).filter(line => line.trim()).map(line => {
        const values = line.split(',').map(v => v.trim());
        const obj: any = {};
        headers.forEach((header, index) => { obj[header] = values[index]; });
        return {
          reference: obj.reference || String(Date.now()).slice(-4),
          date_created: obj.date_created || obj.date || new Date().toISOString().split('T')[0],
          vendeur_name: obj.vendeur_name || obj.vendeur || 'V-X',
          vendeur_benefice: Number(obj.vendeur_benefice) || 0,
          cout_production: Number(obj.cout_production) || Number(obj.cost) || 0,
          prix_vente: Number(obj.prix_vente) || 0,
          status: (obj.status as ExternStatus) || ExternStatus.LIVREE_NON_ENCAISSE,
          stock_note: obj.stock_note || ''
        };
      });
      importExtern(importedData);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const exportCSV = () => {
    if (filteredData.length === 0) return;
    const headers = ["reference", "date_created", "vendeur", "cout_production", "vendeur_benefice", "prix_vente", "status", "profit_net"];
    const rows = filteredData.map(item => [
      item.reference,
      item.date_created,
      item.vendeur_name,
      item.cout_production,
      item.vendeur_benefice,
      item.prix_vente,
      item.status,
      Number(item.prix_vente) - (Number(item.cout_production) + Number(item.vendeur_benefice))
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", "commandes_sitweb.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Commandes sitweb</h2>
          <p className="text-slate-500 text-sm">Gestion des commandes directes et commissions vendeurs.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <input type="file" ref={fileInputRef} onChange={handleImportCSV} accept=".csv" className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50">
            <Upload size={16} /> Importer
          </button>
          <button onClick={exportCSV} className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50">
            <Download size={16} /> Exporter
          </button>
          <button type="button" onClick={addExtern} className="flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 shadow-md active:scale-95 transition-all">
            <Plus size={16} /> Nouvelle Commande
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Profit Réel" value={formatPrice(stats.profitReel)} icon={Banknote} color="text-emerald-600" bg="bg-emerald-50" />
        <StatCard label="Total Vendeurs" value={formatPrice(stats.totalVendorBenefice)} icon={User} color="text-purple-600" bg="bg-purple-50" />
        <StatCard label="Attendu" value={formatPrice(stats.profitAttendu)} icon={Clock} color="text-blue-600" bg="bg-blue-50" />
        <StatCard label="Pertes (Retours)" value={formatPrice(stats.pertesTotal)} icon={AlertCircle} color="text-red-600" bg="bg-red-50" />
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50">
          <div className="relative max-w-xl">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" placeholder="Filtre par Ref ou Vendeur..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all text-sm font-medium" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Ref</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Vendeur</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Coût Production</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Vente</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Com. Vendeur</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Status</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Profit Net</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredData.map((item) => {
                const profitNet = Number(item.prix_vente) - (Number(item.cout_production) + Number(item.vendeur_benefice));
                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="p-2 font-mono text-xs font-black text-slate-400">
                      <EditableCell type="number" value={item.reference} onSave={(v) => updateExtern(item.id, 'reference', String(v))} />
                    </td>
                    <td className="p-2 font-bold text-blue-600">
                      <EditableCell value={item.vendeur_name} onSave={(v) => updateExtern(item.id, 'vendeur_name', v)} />
                    </td>
                    <td className="p-2 text-right font-bold text-slate-600">
                      <EditableCell type="number" value={item.cout_production} onSave={(v) => updateExtern(item.id, 'cout_production', v)} />
                    </td>
                    <td className="p-2 text-right font-black text-slate-900">
                      <EditableCell type="number" value={item.prix_vente} onSave={(v) => updateExtern(item.id, 'prix_vente', v)} />
                    </td>
                    <td className="p-2 text-right font-bold text-purple-600">
                      <EditableCell type="number" value={item.vendeur_benefice} onSave={(v) => updateExtern(item.id, 'vendeur_benefice', v)} />
                    </td>
                    <td className="p-2 text-center">
                      <select 
                        value={item.status} 
                        onChange={(e) => updateExtern(item.id, 'status', e.target.value)}
                        className="text-[10px] p-1.5 border-none bg-slate-100 rounded-lg cursor-pointer font-black text-slate-600 uppercase"
                      >
                        {EXTERN_STATUS_OPTIONS.map(opt => <option key={opt} value={opt}>{opt.replace(/_/g, ' ')}</option>)}
                      </select>
                    </td>
                    <td className="p-4 text-right">
                      <span className={`font-black text-sm ${item.status === ExternStatus.LIVREE_ENCAISSE ? 'text-emerald-600' : item.status === ExternStatus.LIVREE_NON_ENCAISSE ? 'text-blue-600' : 'text-red-600'}`}>
                        {formatPrice(profitNet)}
                      </span>
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        type="button"
                        onClick={(e) => handleDelete(e, item.id)}
                        className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50"
                        title="Supprimer la ligne"
                      >
                        <Trash2 size={16} />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CommandesDetail;

import React from 'react';
import { GrosStatus, ExternStatus } from '../types.ts';

interface StatusBadgeProps {
  status: string;
}

const statusConfig: Record<string, { label: string; color: string }> = {
  [GrosStatus.EN_PRODUCTION]: { label: 'En Production', color: 'bg-yellow-100 text-yellow-700' },
  [GrosStatus.EN_LIVRAISON]: { label: 'En Livraison', color: 'bg-blue-100 text-blue-700' },
  [GrosStatus.LIVREE_NON_ENCAISSE]: { label: 'Livré (Non Encaissé)', color: 'bg-purple-100 text-purple-700' },
  [GrosStatus.LIVREE_ENCAISSE]: { label: 'Livré (Encaissé)', color: 'bg-emerald-100 text-emerald-700' },
  [GrosStatus.RETOUR]: { label: 'Retour', color: 'bg-red-100 text-red-700' },
  // Fix: Changed ExternStatus.LIVREE to ExternStatus.LIVREE_ENCAISSE as LIVREE does not exist in ExternStatus enum
  [ExternStatus.LIVREE_ENCAISSE]: { label: 'Livré', color: 'bg-emerald-100 text-emerald-700' },
};

const StatusBadge: React.FC<StatusBadgeProps> = ({ status }) => {
  const config = statusConfig[status] || { label: status, color: 'bg-slate-100 text-slate-700' };

  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${config.color}`}>
      {config.label}
    </span>
  );
};

