import { OffreType } from '../types.ts';

const Dashboard: React.FC = () => {
  const { getDashboardData, getCalculatedGros, getCalculatedSiteweb, offres, charges } = useAppStore();
  const data = getDashboardData();
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const formatCurrency = (val: number) => {
    return val.toLocaleString('fr-DZ') + ' DA';
  };

  const chartData = useMemo(() => {
    const dailyMap: Record<string, number> = {};

    getCalculatedGros().forEach(item => {
      const d = item.date_created;
      const profit = item.prix_vente - item.cost;
      dailyMap[d] = (dailyMap[d] || 0) + profit;
    });

    getCalculatedSiteweb().forEach(item => {
      const d = item.date_created;
      dailyMap[d] = (dailyMap[d] || 0) + item.profit_net;
    });

    offres.forEach(item => {
      const d = item.date;
      const val = item.type === OffreType.REVENUE ? Number(item.montant) : -Number(item.montant);
      dailyMap[d] = (dailyMap[d] || 0) + val;
    });

    charges.forEach(item => {
      const d = item.date;
      dailyMap[d] = (dailyMap[d] || 0) - Number(item.montant);
    });

    const sortedDates = Object.keys(dailyMap).sort();
    let results = sortedDates.map(date => ({
      date,
      profit: dailyMap[date],
      formattedDate: new Date(date).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' })
    }));

    if (dateStart) results = results.filter(r => r.date >= dateStart);
    if (dateEnd) results = results.filter(r => r.date <= dateEnd);

    return results.length > 0 ? results : [{ date: '', profit: 0, formattedDate: '' }];
  }, [getCalculatedGros, getCalculatedSiteweb, offres, charges, dateStart, dateEnd]);

  const kpis = [
    { label: 'Encaisse Réel', value: data.encaisse_reel, icon: Banknote, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'Profit Attendu', value: data.profit_attendu, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Pertes (Retours)', value: data.pertes, icon: AlertCircle, color: 'text-red-600', bg: 'bg-red-50' },
    { label: 'Les Charges', value: data.total_charges, icon: Wallet, color: 'text-orange-600', bg: 'bg-orange-50' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Synthèse financière et opérationnelle globale.</p>
        </div>
        <div className="flex items-center gap-4 bg-white p-2 rounded-2xl border border-slate-200 shadow-sm self-start">
          <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
            <Calendar size={16} className="text-blue-500" />
            <input type="date" value={dateStart} onChange={(e) => setDateStart(e.target.value)} className="bg-transparent text-xs font-bold outline-none text-slate-700" />
            <span className="text-xs text-slate-300 font-bold">à</span>
            <input type="date" value={dateEnd} onChange={(e) => setDateEnd(e.target.value)} className="bg-transparent text-xs font-bold outline-none text-slate-700" />
          </div>
        </div>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md">
            <div className={`w-12 h-12 rounded-2xl ${kpi.bg} flex items-center justify-center mb-6`}>
              <kpi.icon className={kpi.color} size={24} />
            </div>
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{kpi.label}</p>
            <h3 className="text-2xl font-black text-slate-900">{formatCurrency(kpi.value)}</h3>
          </div>
        ))}
      </div>
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h4 className="font-bold text-slate-800 text-lg">Performance Analytique</h4>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">Bilan Quotidien Net</span>
          </div>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="formattedDate" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }} tickFormatter={(val) => `${(val / 1000).toFixed(0)}k`} />
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '12px', fontWeight: 'bold', padding: '12px' }} formatter={(value: number) => [formatCurrency(value), 'Profit Net']} labelStyle={{ color: '#64748b', marginBottom: '4px' }} />
                <Area type="monotone" dataKey="profit" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorProfit)" animationDuration={1500} />
