          </div>
          <div className="relative z-10 space-y-3 mt-12">
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">Flux Offres Net</span>
               <span className={`text-xs font-black ${data.net_offres >= 0 ? 'text-emerald-400' : 'text-orange-400'}`}>{formatCurrency(data.net_offres)}</span>
            </div>
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">Ratio Charges/Profit</span>
               <span className="text-xs font-black text-slate-300">{data.encaisse_reel > 0 ? ((data.total_charges / (data.encaisse_reel + data.profit_attendu)) * 100).toFixed(1) : 0}%</span>
            </div>
          </div>
          <TrendingUp size={150} className="absolute -bottom-10 -right-10 text-white/5 rotate-12" />
        </div>
      </div>
    </div>
  );
};

