        >
          <Plus size={18} /> Nouveau Client/Service
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <StatCard label="Chiffre d'Affaires Services" value={formatPrice(stats.totalRev)} icon={Target} color="text-blue-600" bg="bg-blue-50" />
        <StatCard label="Charges Spécifiques Clients" value={formatPrice(stats.totalCharges)} icon={Wallet} color="text-orange-600" bg="bg-orange-50" />
        <StatCard label="Bénéfice Net Services" value={formatPrice(stats.netProfit)} icon={Zap} color="text-emerald-600" bg="bg-emerald-50" />
      </div>

      <div className="bg-white border border-slate-100 rounded-[2rem] shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-50 bg-slate-50/30">
          <div className="relative max-w-xl">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
