import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeSiteweb, Offre, InventoryItem, Charge, MarketingService,
  CalculatedGros, CalculatedSiteweb, CalculatedMarketing, DashboardData,
  GrosStatus, SitewebStatus, OffreType, MarketingStatus
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  siteweb: CommandeSiteweb[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  marketingServices: MarketingService[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateSiteweb: (id: string, field: keyof CommandeSiteweb, value: any) => void;
  addSiteweb: () => void;
  duplicateSiteweb: (id: string) => void;
  deleteSiteweb: (id: string) => void;
  importSiteweb: (data: any[]) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedSiteweb: () => CalculatedSiteweb[];
  getCalculatedMarketing: () => CalculatedMarketing[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  importInventory: (data: any[]) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  importCharges: (data: any[]) => void;
  updateMarketing: (id: string, field: keyof MarketingService, value: any) => void;
  addMarketing: () => void;
  deleteMarketing: (id: string) => void;
}

const AppContext = createContext<AppState | undefined>(undefined);

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [siteweb, setSiteweb] = useState<CommandeSiteweb[]>(() => {
    const stored = localStorage.getItem('merch_dz_siteweb');
    if (stored) return JSON.parse(stored);
    const legacy = localStorage.getItem('merch_dz_extern');
    if (legacy) {
        const parsed = JSON.parse(legacy);
        return parsed.map((o: any) => ({
            ...o,
            status: o.status === 'livree_encaisse' ? SitewebStatus.LIVREE : 
                    o.status === 'retour' ? SitewebStatus.RETOUR : SitewebStatus.EN_LIVRAISON
        }));
    }
    return INITIAL_EXTERN.map(o => ({
        ...o,
        status: SitewebStatus.LIVREE
    }));
  });
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));
  const [marketingServices, setMarketingServices] = useState<MarketingService[]>(() => JSON.parse(localStorage.getItem('merch_dz_marketing') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_siteweb', JSON.stringify(siteweb));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
    localStorage.setItem('merch_dz_marketing', JSON.stringify(marketingServices));
  }, [gros, siteweb, offres, inventory, charges, marketingServices]);

  const syncData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('siteweb_orders').upsert({ id: 'current_state', data: siteweb }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges }),
        supabase.from('marketing_services').upsert({ id: 'current_state', data: marketingServices })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, siteweb, offres, inventory, charges, marketingServices]);

  const login = useCallback(() => true, []);
  const logout = useCallback(() => {}, []);

  const updateGros = useCallback((id: string, field: keyof CommandeGros, value: any) => 
    setGros(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addGros = useCallback(() => {
    setGros(prevGros => {
      // Automatic reference generation: find max G{n} and increment
      const refs = prevGros
        .map(i => {
          const match = i.reference.match(/^G(\d+)$/);
          return match ? parseInt(match[1], 10) : 0;
        });
      const maxRefNum = refs.length > 0 ? Math.max(...refs) : 0;
      const nextReference = `G${maxRefNum + 1}`;

      const newOrder: CommandeGros = { 
        id: generateId(), 
        reference: nextReference, 
        client_name: '', 
        client_phone: '', 
        date_created: new Date().toISOString().split('T')[0], 
        prix_achat_article: 0, 
        impression: false, 
        prix_impression: 0, 
        prix_vente: 0, 
        status: GrosStatus.EN_PRODUCTION, 
        stock_note: '' 
      };
      return [newOrder, ...prevGros];
    });
  }, []);

  const deleteGros = useCallback((id: string) => setGros(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importGros = useCallback((data: any[]) => setGros(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateSiteweb = useCallback((id: string, field: keyof CommandeSiteweb, value: any) => 
    setSiteweb(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addSiteweb = useCallback(() => 
    setSiteweb(p => [{ id: generateId(), reference: String(Date.now()).slice(-6), date_created: new Date().toISOString().split('T')[0], cout_article: 0, cout_impression: 0, prix_vente: 0, status: SitewebStatus.EN_LIVRAISON, stock_note: '', vendeur_name: 'V-X', vendeur_benefice: 0 }, ...p]), []);
  const duplicateSiteweb = useCallback((id: string) => {
    const target = siteweb.find(i => String(i.id) === String(id));
    if (target) {
        const duplicated = { ...target, id: generateId(), reference: target.reference + '-copy' };
        setSiteweb(p => [duplicated, ...p]);
    }
  }, [siteweb]);
  const deleteSiteweb = useCallback((id: string) => setSiteweb(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importSiteweb = useCallback((data: any[]) => setSiteweb(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateOffre = useCallback((id: string, field: keyof Offre, value: any) => 
    setOffres(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addOffre = useCallback(() => 
    setOffres(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }, ...p]), []);
  const deleteOffre = useCallback((id: string) => setOffres(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importOffres = useCallback((data: any[]) => setOffres(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateInventory = useCallback((id: string, field: keyof InventoryItem, value: any) => 
    setInventory(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addInventory = useCallback(() => 
    setInventory(p => [{ id: generateId(), name: 'Nouveau Stock', sku: 'SKU-'+Date.now(), quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }, ...p]), []);
  const deleteInventory = useCallback((id: string) => setInventory(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importInventory = useCallback((data: any[]) => setInventory(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateCharge = useCallback((id: string, field: keyof Charge, value: any) => 
    setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addCharge = useCallback((label: string = 'Autre') => 
    setCharges(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }, ...p]), []);
  const deleteCharge = useCallback((id: string) => setCharges(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importCharges = useCallback((data: any[]) => setCharges(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateMarketing = useCallback((id: string, field: keyof MarketingService, value: any) => 
    setMarketingServices(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addMarketing = useCallback(() => 
    setMarketingServices(p => [{ id: generateId(), client_name: 'Nouveau Client', service_description: '', date: new Date().toISOString().split('T')[0], revenue: 0, client_charges: 0, status: MarketingStatus.EN_ATTENTE }, ...p]), []);
  const deleteMarketing = useCallback((id: string) => setMarketingServices(prev => prev.filter(i => String(i.id) !== String(id))), []);

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { 
      ...i, 
      cost, 
      profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, 
      profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, 
      perte: i.status === GrosStatus.RETOUR ? cost : 0 
    };
  }), [gros]);

  const getCalculatedSiteweb = useCallback((): CalculatedSiteweb[] => siteweb.map(i => {
    const production_fees = Number(i.cout_article) + Number(i.cout_impression);
    const profit_net = Number(i.prix_vente) - (production_fees + Number(i.vendeur_benefice));
    return { ...i, profit_net };
  }), [siteweb]);

  const getCalculatedMarketing = useCallback((): CalculatedMarketing[] => marketingServices.map(i => ({
    ...i,
    net_profit: i.status === MarketingStatus.TERMINE 
      ? Number(i.revenue) - Number(i.client_charges) 
      : 0
  })), [marketingServices]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();

    const encaisse = cGros.reduce((a, c) => a + c.profit_encaisse, 0) + 
                     siteweb.filter(o => o.status === SitewebStatus.LIVREE).reduce((a, c) => {
                        const prod = Number(c.cout_article) + Number(c.cout_impression);
                        return a + (Number(c.prix_vente) - (prod + Number(c.vendeur_benefice)));
                     }, 0);

    const attendu = cGros.reduce((a, c) => a + c.profit_attendu, 0) + 
                    siteweb.filter(o => o.status === SitewebStatus.EN_LIVRAISON || o.status === SitewebStatus.LIVREE_NON_ENCAISSEE).reduce((a, c) => {
                        const prod = Number(c.cout_article) + Number(c.cout_impression);
                        return a + (Number(c.prix_vente) - (prod + Number(c.vendeur_benefice)));
                    }, 0);

    const pertes = cGros.reduce((a, c) => a + c.perte, 0) + 
                   siteweb.filter(o => o.status === SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression)), 0);

    const net_offres = offres.reduce((a, c) => c.type === OffreType.REVENUE ? a + Number(c.montant) : a - Number(c.montant), 0);
    const total_charges = charges.reduce((a, c) => a + Number(c.montant), 0);

    return { encaisse_reel: encaisse, profit_attendu: attendu, pertes, net_offres, total_charges, profit_net_final: encaisse + attendu + net_offres - pertes - total_charges };
  }, [getCalculatedGros, siteweb, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, siteweb, offres, inventory, charges, marketingServices, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, 
      updateSiteweb, addSiteweb, duplicateSiteweb, deleteSiteweb, importSiteweb,
      updateOffre, addOffre, deleteOffre, importOffres, 
      updateInventory, addInventory, deleteInventory, importInventory,
      updateCharge, addCharge, deleteCharge, importCharges,
      updateMarketing, addMarketing, deleteMarketing,
      getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("Store context mismatch");
  return context;
};

import React, { useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import StatCard from '../components/StatCard.tsx';
import { MarketingStatus } from '../types.ts';
import { Plus, Search, UserCheck, Wallet, Zap, Trash2, Calendar, Target } from 'lucide-react';

const MarketingClient: React.FC = () => {
  const { getCalculatedMarketing, updateMarketing, addMarketing, deleteMarketing } = useAppStore();
  const allData = getCalculatedMarketing();
  const [searchTerm, setSearchTerm] = useState('');

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      return (item.client_name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
             (item.service_description || '').toLowerCase().includes(searchTerm.toLowerCase());
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [allData, searchTerm]);

  const stats = useMemo(() => {
    // Only count revenue and charges for completed projects for the KPI cards as per the new rules
    const realizedData = filteredData.filter(i => i.status === MarketingStatus.TERMINE);
    const totalRev = realizedData.reduce((acc, curr) => acc + Number(curr.revenue), 0);
    const totalCharges = realizedData.reduce((acc, curr) => acc + Number(curr.client_charges), 0);

    // Net profit is already handled in the store (0 if not TERMINE), so we can just sum it up
    const netProfit = filteredData.reduce((acc, curr) => acc + curr.net_profit, 0);

    return { totalRev, totalCharges, netProfit };
  }, [filteredData]);

  const formatPrice = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

  const handleDelete = (id: string) => {
    if (window.confirm('Supprimer définitivement ce suivi client marketing ?')) {
      deleteMarketing(id);
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Marketing Clients</h2>
          <p className="text-slate-500 text-sm font-medium">Analyse de rentabilité par service et par client.</p>
        </div>
        <button 
          onClick={addMarketing} 
          className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-sm font-black hover:bg-blue-700 shadow-xl shadow-blue-500/20 active:scale-95 transition-all self-start"
        >
          <Plus size={18} /> Nouveau Client/Service
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <StatCard label="Chiffre d'Affaires Encaissé" value={formatPrice(stats.totalRev)} icon={Target} color="text-blue-600" bg="bg-blue-50" />
        <StatCard label="Charges Services Finis" value={formatPrice(stats.totalCharges)} icon={Wallet} color="text-orange-600" bg="bg-orange-50" />
        <StatCard label="Bénéfice Net Réalisé" value={formatPrice(stats.netProfit)} icon={Zap} color="text-emerald-600" bg="bg-emerald-50" />
      </div>

      <div className="bg-white border border-slate-100 rounded-[2rem] shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-50 bg-slate-50/30">
          <div className="relative max-w-xl">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Filtrer par Client ou Service..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 transition-all text-sm font-medium" 
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Client & Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px]">Description du Service</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Revenu Brut</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Charges Client</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Status</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-right">Bénéfice Net</th>
                <th className="p-4 font-bold text-slate-500 uppercase tracking-tighter text-[10px] text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredData.map((item) => (
                <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="p-3">
                    <EditableCell value={item.client_name} onSave={v => updateMarketing(item.id, 'client_name', v)} className="font-black text-slate-800" />
                    <div className="flex items-center gap-1 px-2 text-[10px] text-slate-400 font-bold">
                      <Calendar size={10} />
                      <EditableCell type="date" value={item.date} onSave={v => updateMarketing(item.id, 'date', v)} className="p-0 min-h-0 bg-transparent" />
                    </div>
                  </td>
                  <td className="p-3">
                    <EditableCell value={item.service_description} onSave={v => updateMarketing(item.id, 'service_description', v)} className="text-slate-600 font-medium italic text-sm" />
                  </td>
                  <td className="p-3 text-right font-black text-slate-900">
                    <EditableCell type="number" value={item.revenue} onSave={v => updateMarketing(item.id, 'revenue', v)} className="text-right" />
                  </td>
                  <td className="p-3 text-right font-bold text-orange-600">
                    <EditableCell type="number" value={item.client_charges} onSave={v => updateMarketing(item.id, 'client_charges', v)} className="text-right" />
                  </td>
                  <td className="p-3 text-center">
                    <select 
                      value={item.status} 
                      onChange={(e) => updateMarketing(item.id, 'status', e.target.value)}
                      className={`text-[10px] px-3 py-1.5 rounded-xl border-none font-black uppercase tracking-widest cursor-pointer transition-colors
                        ${item.status === MarketingStatus.TERMINE ? 'bg-emerald-50 text-emerald-700' : 
                          item.status === MarketingStatus.EN_COURS ? 'bg-blue-50 text-blue-700' : 
                          item.status === MarketingStatus.ANNULE ? 'bg-red-50 text-red-700' : 'bg-slate-100 text-slate-500'}`}
                    >
                      {Object.values(MarketingStatus).map(opt => <option key={opt} value={opt}>{opt.replace(/_/g, ' ')}</option>)}
                    </select>
                  </td>
                  <td className={`p-5 text-right font-black text-sm ${item.net_profit > 0 ? 'text-emerald-600' : 'text-slate-400'}`}>
                    {formatPrice(item.net_profit)}
                  </td>
                  <td className="p-3 text-center">
                    <button 
                      onClick={() => handleDelete(item.id)}
                      className="p-2 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                    >
                      <Trash2 size={16} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={7} className="p-20 text-center">
                    <div className="flex flex-col items-center gap-4">
                      <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300">
                        <UserCheck size={32} />
                      </div>
                      <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Aucune donnée marketing client</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default MarketingClient;

export enum GrosStatus {
  EN_PRODUCTION = 'en_production',
  EN_LIVRAISON = 'en_livraison',
  LIVREE_NON_ENCAISSE = 'livree_non_encaisse',
  LIVREE_ENCAISSE = 'livree_encaisse',
  RETOUR = 'retour'
}

export enum SitewebStatus {
  LIVREE = 'livrée',
  LIVREE_NON_ENCAISSEE = 'livrée_non_encaissée',
  EN_LIVRAISON = 'en_livraison',
  RETOUR = 'retour'
}

export enum MarketingStatus {
  EN_COURS = 'en_cours',
  TERMINE = 'termine',
  ANNULE = 'annule'
}

export enum OffreType {
  REVENUE = 'revenue',
  EXPENSE = 'expense'
}

export enum OffreCategory {
  ADS = 'ads',
  CREATIVE = 'creative',
  SUBSCRIPTIONS = 'subscriptions',
  OTHER = 'other'
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  min_stock: number;
  unit_cost: number;
  supplier: string;
}

export interface Charge {
  id: string;
  date: string;
  label: string;
  montant: number;
  note: string;
}

export interface CommandeGros {
  id: string;
  reference: string;
  client_name: string;
  client_phone: string;
  date_created: string;
  prix_achat_article: number;
  impression: boolean;
  prix_impression: number;
  prix_vente: number;
  status: GrosStatus;
  stock_note: string;
}

export interface CommandeSiteweb {
  id: string;
  reference: string;
  date_created: string;
  cout_article: number;
  cout_impression: number;
  prix_vente: number;
  status: SitewebStatus;
  stock_note: string;
  vendeur_name: string;
  vendeur_benefice: number;
}

export interface MarketingService {
  id: string;
  client_name: string;
  service_description: string;
  date: string;
  revenue: number;
  client_charges: number;
  status: MarketingStatus;
}

export interface Offre {
  id: string;
  date: string;
  type: OffreType;
  montant: number;
  category: OffreCategory;
  description: string;
}

export interface CalculatedGros extends CommandeGros {
  cost: number;
  profit_encaisse: number;
  profit_attendu: number;
  perte: number;
}

export interface CalculatedSiteweb extends CommandeSiteweb {
  profit_net: number;
}

// Added missing interface used in store.tsx
export interface CalculatedMarketing extends MarketingService {
  net_profit: number;
}

export interface DashboardData {
  encaisse_reel: number;
  profit_attendu: number;
  pertes: number;
  net_offres: number;
  total_charges: number;
  profit_net_final: number;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeSiteweb, Offre, InventoryItem, Charge, MarketingService,
  CalculatedGros, CalculatedSiteweb, CalculatedMarketing, DashboardData,
  GrosStatus, SitewebStatus, OffreType, MarketingStatus
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

const SUPABASE_URL = (window as any).process?.env?.SUPABASE_URL || '';
const SUPABASE_KEY = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

interface AppState {
  gros: CommandeGros[];
  siteweb: CommandeSiteweb[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  marketingServices: MarketingService[];
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  login: (password: string) => boolean;
  logout: () => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => void;
  addGros: () => void;
  deleteGros: (id: string) => void;
  importGros: (data: any[]) => void;
  updateSiteweb: (id: string, field: keyof CommandeSiteweb, value: any) => void;
  addSiteweb: () => void;
  duplicateSiteweb: (id: string) => void;
  deleteSiteweb: (id: string) => void;
  importSiteweb: (data: any[]) => void;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedSiteweb: () => CalculatedSiteweb[];
  getCalculatedMarketing: () => CalculatedMarketing[];
  getDashboardData: () => DashboardData;
  syncData: () => Promise<void>;
  updateOffre: (id: string, field: keyof Offre, value: any) => void;
  addOffre: () => void;
  deleteOffre: (id: string) => void;
  importOffres: (data: any[]) => void;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => void;
  addInventory: () => void;
  deleteInventory: (id: string) => void;
  importInventory: (data: any[]) => void;
  updateCharge: (id: string, field: keyof Charge, value: any) => void;
  addCharge: (label?: string) => void;
  deleteCharge: (id: string) => void;
  importCharges: (data: any[]) => void;
  updateMarketing: (id: string, field: keyof MarketingService, value: any) => void;
  addMarketing: () => void;
  deleteMarketing: (id: string) => void;
}

const AppContext = createContext<AppState | undefined>(undefined);

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(() => localStorage.getItem('merch_dz_last_sync'));

  const [gros, setGros] = useState<CommandeGros[]>(() => JSON.parse(localStorage.getItem('merch_dz_gros') || JSON.stringify(INITIAL_GROS)));
  const [siteweb, setSiteweb] = useState<CommandeSiteweb[]>(() => {
    const stored = localStorage.getItem('merch_dz_siteweb');
    if (stored) return JSON.parse(stored);
    const legacy = localStorage.getItem('merch_dz_extern');
    if (legacy) {
        const parsed = JSON.parse(legacy);
        return parsed.map((o: any) => ({
            ...o,
            status: o.status === 'livree_encaisse' ? SitewebStatus.LIVREE : 
                    o.status === 'retour' ? SitewebStatus.RETOUR : SitewebStatus.EN_LIVRAISON
        }));
    }
    return INITIAL_EXTERN.map(o => ({
        ...o,
        status: SitewebStatus.LIVREE
    }));
  });
  const [offres, setOffres] = useState<Offre[]>(() => JSON.parse(localStorage.getItem('merch_dz_offres') || JSON.stringify(INITIAL_OFFRES)));
  const [inventory, setInventory] = useState<InventoryItem[]>(() => JSON.parse(localStorage.getItem('merch_dz_inventory') || '[]'));
  const [charges, setCharges] = useState<Charge[]>(() => JSON.parse(localStorage.getItem('merch_dz_charges') || '[]'));
  const [marketingServices, setMarketingServices] = useState<MarketingService[]>(() => JSON.parse(localStorage.getItem('merch_dz_marketing') || '[]'));

  useEffect(() => {
    localStorage.setItem('merch_dz_gros', JSON.stringify(gros));
    localStorage.setItem('merch_dz_siteweb', JSON.stringify(siteweb));
    localStorage.setItem('merch_dz_offres', JSON.stringify(offres));
    localStorage.setItem('merch_dz_inventory', JSON.stringify(inventory));
    localStorage.setItem('merch_dz_charges', JSON.stringify(charges));
    localStorage.setItem('merch_dz_marketing', JSON.stringify(marketingServices));
  }, [gros, siteweb, offres, inventory, charges, marketingServices]);

  const syncData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('gros_orders').upsert({ id: 'current_state', data: gros }),
        supabase.from('siteweb_orders').upsert({ id: 'current_state', data: siteweb }),
        supabase.from('offres_frais').upsert({ id: 'current_state', data: offres }),
        supabase.from('inventory').upsert({ id: 'current_state', data: inventory }),
        supabase.from('les_charges').upsert({ id: 'current_state', data: charges }),
        supabase.from('marketing_services').upsert({ id: 'current_state', data: marketingServices })
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, siteweb, offres, inventory, charges, marketingServices]);

  const login = useCallback(() => true, []);
  const logout = useCallback(() => {}, []);

  const updateGros = useCallback((id: string, field: keyof CommandeGros, value: any) => 
    setGros(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);

  const addGros = useCallback(() => {
    setGros(prevGros => {
      // Automatic reference generation: find max G{n} and increment
      const refs = prevGros
        .map(i => {
          const match = i.reference.match(/^G(\d+)$/);
          return match ? parseInt(match[1], 10) : 0;
        });
      const maxRefNum = refs.length > 0 ? Math.max(...refs) : 0;
      const nextReference = `G${maxRefNum + 1}`;

      const newOrder: CommandeGros = { 
        id: generateId(), 
        reference: nextReference, 
        client_name: '', 
        client_phone: '', 
        date_created: new Date().toISOString().split('T')[0], 
        prix_achat_article: 0, 
        impression: false, 
        prix_impression: 0, 
        prix_vente: 0, 
        status: GrosStatus.EN_PRODUCTION, 
        stock_note: '' 
      };
      return [newOrder, ...prevGros];
    });
  }, []);

  const deleteGros = useCallback((id: string) => setGros(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importGros = useCallback((data: any[]) => setGros(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateSiteweb = useCallback((id: string, field: keyof CommandeSiteweb, value: any) => 
    setSiteweb(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addSiteweb = useCallback(() => 
    setSiteweb(p => [{ id: generateId(), reference: String(Date.now()).slice(-6), date_created: new Date().toISOString().split('T')[0], cout_article: 0, cout_impression: 0, prix_vente: 0, status: SitewebStatus.EN_LIVRAISON, stock_note: '', vendeur_name: 'V-X', vendeur_benefice: 0 }, ...p]), []);
  const duplicateSiteweb = useCallback((id: string) => {
    const target = siteweb.find(i => String(i.id) === String(id));
    if (target) {
        const duplicated = { ...target, id: generateId(), reference: target.reference + '-copy' };
        setSiteweb(p => [duplicated, ...p]);
    }
  }, [siteweb]);
  const deleteSiteweb = useCallback((id: string) => setSiteweb(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importSiteweb = useCallback((data: any[]) => setSiteweb(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateOffre = useCallback((id: string, field: keyof Offre, value: any) => 
    setOffres(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addOffre = useCallback(() => 
    setOffres(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], type: OffreType.EXPENSE, montant: 0, category: 'other' as any, description: '' }, ...p]), []);
  const deleteOffre = useCallback((id: string) => setOffres(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importOffres = useCallback((data: any[]) => setOffres(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateInventory = useCallback((id: string, field: keyof InventoryItem, value: any) => 
    setInventory(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addInventory = useCallback(() => 
    setInventory(p => [{ id: generateId(), name: 'Nouveau Stock', sku: 'SKU-'+Date.now(), quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' }, ...p]), []);
  const deleteInventory = useCallback((id: string) => setInventory(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importInventory = useCallback((data: any[]) => setInventory(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateCharge = useCallback((id: string, field: keyof Charge, value: any) => 
    setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addCharge = useCallback((label: string = 'Autre') => 
    setCharges(p => [{ id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' }, ...p]), []);
  const deleteCharge = useCallback((id: string) => setCharges(prev => prev.filter(item => String(item.id) !== String(id))), []);
  const importCharges = useCallback((data: any[]) => setCharges(prev => [...data.map(i => ({...i, id: generateId()})), ...prev]), []);

  const updateMarketing = useCallback((id: string, field: keyof MarketingService, value: any) => 
    setMarketingServices(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)), []);
  const addMarketing = useCallback(() => 
    setMarketingServices(p => [{ id: generateId(), client_name: 'Nouveau Client', service_description: '', date: new Date().toISOString().split('T')[0], revenue: 0, client_charges: 0, status: MarketingStatus.EN_COURS }, ...p]), []);
  const deleteMarketing = useCallback((id: string) => setMarketingServices(prev => prev.filter(i => String(i.id) !== String(id))), []);

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const cost = Number(i.prix_achat_article) + Number(i.prix_impression);
    const profit = Number(i.prix_vente) - cost;
    return { 
      ...i, 
      cost, 
      profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0, 
      profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0, 
      perte: i.status === GrosStatus.RETOUR ? cost : 0 
    };
  }), [gros]);

  const getCalculatedSiteweb = useCallback((): CalculatedSiteweb[] => siteweb.map(i => {
    const production_fees = Number(i.cout_article) + Number(i.cout_impression);
    const profit_net = Number(i.prix_vente) - (production_fees + Number(i.vendeur_benefice));
    return { ...i, profit_net };
  }), [siteweb]);

  const getCalculatedMarketing = useCallback((): CalculatedMarketing[] => marketingServices.map(i => ({
    ...i,
    net_profit: i.status === MarketingStatus.TERMINE 
      ? Number(i.revenue) - Number(i.client_charges) 
      : 0
  })), [marketingServices]);

  const getDashboardData = useCallback((): DashboardData => {
    const cGros = getCalculatedGros();

    const encaisse = cGros.reduce((a, c) => a + c.profit_encaisse, 0) + 
                     siteweb.filter(o => o.status === SitewebStatus.LIVREE).reduce((a, c) => {
                        const prod = Number(c.cout_article) + Number(c.cout_impression);
                        return a + (Number(c.prix_vente) - (prod + Number(c.vendeur_benefice)));
                     }, 0);

    const attendu = cGros.reduce((a, c) => a + c.profit_attendu, 0) + 
                    siteweb.filter(o => o.status === SitewebStatus.EN_LIVRAISON || o.status === SitewebStatus.LIVREE_NON_ENCAISSEE).reduce((a, c) => {
                        const prod = Number(c.cout_article) + Number(c.cout_impression);
                        return a + (Number(c.prix_vente) - (prod + Number(c.vendeur_benefice)));
                    }, 0);

    const pertes = cGros.reduce((a, c) => a + c.perte, 0) + 
                   siteweb.filter(o => o.status === SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression)), 0);

    const net_offres = offres.reduce((a, c) => c.type === OffreType.REVENUE ? a + Number(c.montant) : a - Number(c.montant), 0);
    const total_charges = charges.reduce((a, c) => a + Number(c.montant), 0);

    return { encaisse_reel: encaisse, profit_attendu: attendu, pertes, net_offres, total_charges, profit_net_final: encaisse + attendu + net_offres - pertes - total_charges };
  }, [getCalculatedGros, siteweb, offres, charges]);

  return (
    <AppContext.Provider value={{ 
      gros, siteweb, offres, inventory, charges, marketingServices, isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, 
      updateSiteweb, addSiteweb, duplicateSiteweb, deleteSiteweb, importSiteweb,
      updateOffre, addOffre, deleteOffre, importOffres, 
      updateInventory, addInventory, deleteInventory, importInventory,
      updateCharge, addCharge, deleteCharge, importCharges,
      updateMarketing, addMarketing, deleteMarketing,
      getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, getDashboardData, syncData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("Store context mismatch");
  return context;
};

import React, { useRef, useState, useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import EditableCell from '../components/EditableCell.tsx';
import { 
  Plus, 
  Minus,
  Search, 
  Package, 
  AlertTriangle, 
  Layers, 
  Trash2, 
  Download, 
  Upload, 
  ChevronRight,
  TrendingDown,
  Box
} from 'lucide-react';

const Inventory: React.FC = () => {
  const { inventory, updateInventory, addInventory, deleteInventory, importInventory } = useAppStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'low' | 'out'>('all');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredData = useMemo(() => {
    return inventory.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          item.sku.toLowerCase().includes(searchTerm.toLowerCase());

      if (filterStatus === 'low') return matchesSearch && item.quantity <= item.min_stock && item.quantity > 0;
      if (filterStatus === 'out') return matchesSearch && item.quantity === 0;

      return matchesSearch;
    }).sort((a, b) => a.quantity - b.quantity); // Prioritize low stock items in view
  }, [inventory, searchTerm, filterStatus]);

  const stats = useMemo(() => {
    const lowStockCount = inventory.filter(i => i.quantity <= i.min_stock && i.quantity > 0).length;
    const outOfStockCount = inventory.filter(i => i.quantity === 0).length;
    const totalValue = inventory.reduce((acc, i) => acc + (i.quantity * i.unit_cost), 0);
    return { lowStockCount, outOfStockCount, totalValue };
  }, [inventory]);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('Voulez-vous supprimer définitivement cet article du stock ?')) {
      deleteInventory(id);
    }
  };

  const adjustQuantity = (id: string, current: number, delta: number) => {
    const newVal = Math.max(0, current + delta);
    updateInventory(id, 'quantity', newVal);
  };

  const handleImportCSV = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
      const importedData = lines.slice(1).filter(line => line.trim()).map(line => {
        const values = line.split(',').map(v => v.trim());
        const obj: any = {};
        headers.forEach((header, index) => { obj[header] = values[index]; });
        return {
          name: obj.name || obj.item || '',
          sku: obj.sku || `SKU-${Date.now()}`,
          quantity: Number(obj.quantity) || 0,
          min_stock: Number(obj.min_stock) || 5,
          unit_cost: Number(obj.unit_cost) || Number(obj.cost) || 0,
          supplier: obj.supplier || ''
        };
      });
      importInventory(importedData);
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const exportCSV = () => {
    if (filteredData.length === 0) return;
    const headers = ["name", "sku", "quantity", "min_stock", "unit_cost", "supplier"];
    const rows = filteredData.map(item => [
      item.name,
      item.sku,
      item.quantity,
      item.min_stock,
      item.unit_cost,
      item.supplier
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", "inventaire_stock.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Inventaire & Stock</h2>
          <p className="text-slate-500 font-medium">Gestion intelligente et alertes de réapprovisionnement.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <input type="file" ref={fileInputRef} onChange={handleImportCSV} accept=".csv" className="hidden" />
          <button 
            onClick={() => fileInputRef.current?.click()} 
            className="flex items-center gap-2 px-4 py-2.5 bg-white border border-slate-200 text-slate-700 rounded-2xl text-sm font-bold hover:bg-slate-50 transition-all shadow-sm"
          >
            <Upload size={18} /> Importer
          </button>
          <button 
            onClick={exportCSV} 
            className="flex items-center gap-2 px-4 py-2.5 bg-white border border-slate-200 text-slate-700 rounded-2xl text-sm font-bold hover:bg-slate-50 transition-all shadow-sm"
          >
            <Download size={18} /> Exporter
          </button>
          <button 
            onClick={addInventory} 
            className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-2xl text-sm font-black hover:bg-blue-700 shadow-xl shadow-blue-500/20 active:scale-95 transition-all"
          >
            <Plus size={18} /> Nouvel Article
          </button>
        </div>
      </div>

      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-blue-50 rounded-2xl text-blue-600 transition-transform group-hover:scale-110">
              <Package size={28}/>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total SKUs</p>
              <p className="text-2xl font-black text-slate-800">{inventory.length}</p>
            </div>
          </div>
          <ChevronRight size={20} className="text-slate-200" />
        </div>

        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
          <div className="flex items-center gap-4">
            <div className={`p-4 ${stats.lowStockCount > 0 ? 'bg-orange-50 text-orange-600' : 'bg-slate-50 text-slate-300'} rounded-2xl transition-transform group-hover:scale-110`}>
              <AlertTriangle size={28}/>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Stock Critique</p>
              <p className={`text-2xl font-black ${stats.lowStockCount > 0 ? 'text-orange-600' : 'text-slate-800'}`}>{stats.lowStockCount + stats.outOfStockCount}</p>
            </div>
          </div>
          <ChevronRight size={20} className="text-slate-200" />
        </div>

        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-emerald-50 rounded-2xl text-emerald-600 transition-transform group-hover:scale-110">
              <Layers size={28}/>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Valeur Inventaire</p>
              <p className="text-2xl font-black text-emerald-600">{stats.totalValue.toLocaleString()} DA</p>
            </div>
          </div>
          <ChevronRight size={20} className="text-slate-200" />
        </div>
      </div>

      {/* Main Table Container */}
      <div className="bg-white border border-slate-100 rounded-[2.5rem] shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-50 bg-slate-50/30 flex flex-col lg:flex-row lg:items-center gap-6 justify-between">
          <div className="relative max-w-md flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Rechercher nom, SKU, fournisseur..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 transition-all font-medium text-sm" 
            />
          </div>

          <div className="flex items-center gap-2 p-1.5 bg-white border border-slate-200 rounded-2xl">
            <button 
              onClick={() => setFilterStatus('all')}
              className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all ${filterStatus === 'all' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Tous
            </button>
            <button 
              onClick={() => setFilterStatus('low')}
              className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all ${filterStatus === 'low' ? 'bg-orange-600 text-white' : 'text-slate-400 hover:text-orange-600'}`}
            >
              Bas
            </button>
            <button 
              onClick={() => setFilterStatus('out')}
              className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all ${filterStatus === 'out' ? 'bg-red-600 text-white' : 'text-slate-400 hover:text-red-600'}`}
            >
              Rupture
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                <th className="p-5">Article & Détails</th>
                <th className="p-5">SKU / Ref</th>
                <th className="p-5 text-center">Statut</th>
                <th className="p-5 text-right">Quantité</th>
                <th className="p-5 text-right">Prix Unitaire</th>
                <th className="p-5 text-right">Valeur Totale</th>
                <th className="p-5 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredData.map(item => {
                const isOutOfStock = item.quantity === 0;
                const isLowStock = item.quantity <= item.min_stock && !isOutOfStock;

                return (
                  <tr key={item.id} className={`hover:bg-slate-50/50 transition-colors group ${isOutOfStock ? 'bg-red-50/20' : isLowStock ? 'bg-orange-50/20' : ''}`}>
                    <td className="p-3">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-xl ${isOutOfStock ? 'bg-red-100 text-red-600' : isLowStock ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
                          <Box size={16} />
                        </div>
                        <div>
                          <EditableCell value={item.name} onSave={v => updateInventory(item.id, 'name', v)} className="font-bold text-slate-800 p-0 min-h-0" />
                          <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter mt-1">{item.supplier || 'Sans Fournisseur'}</div>
                        </div>
                      </div>
                    </td>
                    <td className="p-3">
                      <EditableCell value={item.sku} onSave={v => updateInventory(item.id, 'sku', v)} className="font-mono text-xs text-slate-500 p-0 min-h-0" />
                    </td>
                    <td className="p-3 text-center">
                      <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest
                        ${isOutOfStock ? 'bg-red-100 text-red-700' : isLowStock ? 'bg-orange-100 text-orange-700' : 'bg-emerald-100 text-emerald-700'}`}>
                        {isOutOfStock ? 'En Rupture' : isLowStock ? 'Stock Bas' : 'En Stock'}
                      </span>
                    </td>
                    <td className="p-3">
                      <div className="flex items-center justify-end gap-3">
                        <button 
                          onClick={() => adjustQuantity(item.id, item.quantity, -1)}
                          className="w-8 h-8 flex items-center justify-center bg-white border border-slate-200 rounded-lg text-slate-400 hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-all shadow-sm"
                        >
                          <Minus size={14} />
                        </button>
                        <div className="w-16 text-right">
                          <EditableCell type="number" value={item.quantity} onSave={v => updateInventory(item.id, 'quantity', v)} className={`text-right font-black text-sm p-0 min-h-0 ${isOutOfStock ? 'text-red-600' : isLowStock ? 'text-orange-600' : 'text-slate-800'}`} />
                        </div>
                        <button 
                          onClick={() => adjustQuantity(item.id, item.quantity, 1)}
                          className="w-8 h-8 flex items-center justify-center bg-white border border-slate-200 rounded-lg text-slate-400 hover:bg-blue-50 hover:text-blue-500 hover:border-blue-200 transition-all shadow-sm"
                        >
                          <Plus size={14} />
                        </button>
                      </div>
                      <div className="text-right text-[10px] text-slate-400 font-bold mt-1 pr-11">Seuil: {item.min_stock}</div>
                    </td>
                    <td className="p-3 text-right">
                      <EditableCell type="number" value={item.unit_cost} onSave={v => updateInventory(item.id, 'unit_cost', v)} className="text-right font-bold text-slate-600 p-0 min-h-0" />
                    </td>
                    <td className="p-3 text-right">
                      <span className="font-black text-slate-900 text-sm">
                        {(item.quantity * item.unit_cost).toLocaleString()} DA
                      </span>
                    </td>
                    <td className="p-3 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <button 
                          type="button" 
                          onClick={(e) => handleDelete(e, item.id)} 
                          className="p-2 text-slate-200 hover:text-red-500 transition-all rounded-xl hover:bg-red-50"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={7} className="p-20 text-center">
                    <div className="flex flex-col items-center gap-4">
                      <div className="p-6 bg-slate-50 rounded-full text-slate-200">
                        <Box size={48} />
                      </div>
                      <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Aucun article ne correspond à votre recherche</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

