        </div>
      </div>
    </div>
  );
};

export default MarketingSpend;

import React, { useMemo, useState } from 'react';
import { useAppStore } from '../store.tsx';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell } from 'recharts';
import { Clock, AlertCircle, Banknote, Calendar, Wallet, TrendingUp, Megaphone, Target } from 'lucide-react';
import { OffreType, MarketingSpendSource, MarketingStatus, GrosStatus, SitewebStatus } from '../types.ts';

const Dashboard: React.FC = () => {
  const { getDashboardData, getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, offres, charges, marketingSpends } = useAppStore();
  const data = getDashboardData();
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const formatCurrency = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

  // Analysis by revenue pillar
  const pillarStats = useMemo(() => {
    // 1. Gros
    const grosRev = getCalculatedGros().filter(i => i.status !== GrosStatus.RETOUR).reduce((a, c) => a + c.prix_vente, 0);
    const grosProd = getCalculatedGros().reduce((a, c) => a + c.cost, 0);
    const grosMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.GROS).reduce((a, c) => a + Number(c.amount), 0);

    // 2. Siteweb
    const swRev = getCalculatedSiteweb().filter(i => i.status === SitewebStatus.LIVREE).reduce((a, c) => a + Number(c.prix_vente), 0);
    const swProd = getCalculatedSiteweb().filter(i => i.status !== SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression) + Number(c.vendeur_benefice)), 0);
    const swMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.SITEWEB).reduce((a, c) => a + Number(c.amount), 0);

    // 3. Offres (Subscriptions)
    const offRev = offres.filter(o => o.type === OffreType.REVENUE).reduce((a, c) => a + Number(c.montant), 0);
    const offExp = offres.filter(o => o.type === OffreType.EXPENSE).reduce((a, c) => a + Number(c.montant), 0);
    const offMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.OFFRES).reduce((a, c) => a + Number(c.amount), 0);

    // 4. Marketing Client (Services)
    const clientRev = getCalculatedMarketing().filter(m => m.status === MarketingStatus.TERMINE).reduce((a, c) => a + Number(c.revenue), 0);
    const clientExp = getCalculatedMarketing().filter(m => m.status === MarketingStatus.TERMINE).reduce((a, c) => a + Number(c.client_charges), 0);
    const clientMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.MARKETING_CLIENT).reduce((a, c) => a + Number(c.amount), 0);

    return [
      { name: 'Gros', rev: grosRev, exp: grosProd, marketing: grosMarketing, net: grosRev - grosProd - grosMarketing },
      { name: 'Retail', rev: swRev, exp: swProd, marketing: swMarketing, net: swRev - swProd - swMarketing },
      { name: 'Plans', rev: offRev, exp: offExp, marketing: offMarketing, net: offRev - offExp - offMarketing },
      { name: 'Services', rev: clientRev, exp: clientExp, marketing: clientMarketing, net: clientRev - clientExp - clientMarketing },
    ];
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, offres, marketingSpends]);

  const kpis = [
    { label: 'Profit Encaissé', value: data.encaisse_reel, icon: Banknote, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'Attendu (En cours)', value: data.profit_attendu, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Marketing Spend', value: data.total_marketing_spend, icon: Megaphone, color: 'text-purple-600', bg: 'bg-purple-50' },
    { label: 'Fixed Charges', value: data.total_charges, icon: Wallet, color: 'text-orange-600', bg: 'bg-orange-50' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Analyse globale: Revenus, Production, Marketing & Net.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpis.map((kpi, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md">
            <div className={`w-12 h-12 rounded-2xl ${kpi.bg} flex items-center justify-center mb-6`}>
              <kpi.icon className={kpi.color} size={24} />
            </div>
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{kpi.label}</p>
            <h3 className="text-2xl font-black text-slate-900">{formatCurrency(kpi.value)}</h3>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 space-y-8">
           {/* Section Pillars Profitability */}
           <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
             <h4 className="font-bold text-slate-800 text-lg mb-6">Rentabilité par Catégorie</h4>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {pillarStats.map(p => (
                  <div key={p.name} className="p-4 rounded-2xl bg-slate-50 border border-slate-100 space-y-3">
                    <p className="text-[10px] font-black uppercase text-blue-600 tracking-wider">{p.name}</p>
                    <div className="space-y-1">
                      <div className="flex justify-between text-[10px] font-bold">
                        <span className="text-slate-400 uppercase">Rev:</span>
                        <span className="text-slate-700">{formatCurrency(p.rev)}</span>
                      </div>
                      <div className="flex justify-between text-[10px] font-bold">
                        <span className="text-slate-400 uppercase">Marketing:</span>
                        <span className="text-purple-600">{formatCurrency(p.marketing)}</span>
                      </div>
                    </div>
                    <div className="pt-2 border-t border-slate-200 flex justify-between items-center">
                       <span className="text-[10px] font-black uppercase text-slate-400">Net:</span>
                       <span className={`text-xs font-black ${p.net >= 0 ? 'text-emerald-600' : 'text-red-500'}`}>{formatCurrency(p.net)}</span>
                    </div>
                  </div>
                ))}
             </div>
           </div>

           <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm h-[350px]">
              <h4 className="font-bold text-slate-800 text-lg mb-6">Distribution Netto Profits</h4>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={pillarStats}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }} />
                  <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8', fontWeight: 600 }} tickFormatter={(val) => `${(val / 1000).toFixed(0)}k`} />
                  <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '11px', fontWeight: 'bold' }} />
                  <Bar dataKey="net" radius={[6, 6, 0, 0]}>
                    {pillarStats.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.net >= 0 ? '#10b981' : '#ef4444'} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
           </div>
        </div>

        <div className="bg-slate-900 text-white p-8 rounded-3xl shadow-xl shadow-slate-200 relative overflow-hidden flex flex-col justify-between h-full">
          <div className="relative z-10">
            <p className="text-blue-400 text-xs font-black uppercase tracking-widest mb-4">Solde Net Final (Global)</p>
            <h4 className="text-4xl font-black mb-4 tracking-tighter">{formatCurrency(data.profit_net_final)}</h4>
            <p className="text-slate-400 text-sm font-medium leading-relaxed">Profit calculé après déduction des coûts de production, des charges fixes et de l'ensemble du budget marketing injecté.</p>
          </div>

          <div className="relative z-10 space-y-3 mt-12">
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">MKT ROI (Global)</span>
               <span className="text-xs font-black text-blue-400">
                {data.total_marketing_spend > 0 ? (( (data.encaisse_reel + data.profit_attendu) / data.total_marketing_spend)).toFixed(2) + 'x' : 'N/A'}
               </span>
            </div>
            <div className="p-4 bg-slate-800/50 rounded-2xl flex items-center justify-between border border-white/5">
               <span className="text-[10px] font-black uppercase text-slate-500">Ratio Marketing</span>
               <span className="text-xs font-black text-slate-300">
                {data.encaisse_reel > 0 ? ((data.total_marketing_spend / (data.encaisse_reel + data.profit_attendu)) * 100).toFixed(1) : 0}%
               </span>
            </div>
          </div>
          <TrendingUp size={150} className="absolute -bottom-10 -right-10 text-white/5 rotate-12" />
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

